package modkit

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"go/format"
	"net/http"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// formatGo renders emitted Go through the standard formatter. Emitters build
// source by string concatenation; running the formatter once here means a
// generated file can never disagree with gofmt, and a syntax error is caught
// inside the transaction instead of at the next build.
func formatGo(file *GeneratedFile) (*GeneratedFile, error) {
	if !strings.HasSuffix(file.Path, ".go") {
		return file, nil
	}
	formatted, err := format.Source([]byte(file.Content))
	if err != nil {
		return nil, fmt.Errorf("%s: generated Go does not parse: %w", file.Path, err)
	}
	file.Content = string(formatted)
	return file, nil
}

// GeneratedFile is one deterministic registry-owned output emitted by the
// generator pipeline. Every path is tool-owned; authored modules never claim
// these targets.
type GeneratedFile struct {
	Path    string
	Content string
}

// genHeader is the shared DO-NOT-EDIT banner for generated Go files. The
// indexSHA ties the output to the exact gogogadget.lock.json it was rendered
// from, so drift is detectable.
func genHeader(modulePath string, lock Lock) string {
	var b strings.Builder
	b.WriteString("// Code generated by ggg sync; DO NOT EDIT.\n")
	b.WriteString("//\n")
	fmt.Fprintf(&b, "// index: %s\n", indexSHA(lock))
	fmt.Fprintf(&b, "// registry: %s\n", lock.RegistryCommit)
	b.WriteString("\n")
	_ = modulePath
	return b.String()
}

// indexSHA is the deterministic digest of the resolved module graph. It changes
// whenever any selected module's revision, contract, or set changes.
func indexSHA(lock Lock) string {
	h := sha256.New()
	for _, id := range lock.Order {
		h.Write([]byte(id))
		h.Write([]byte{0})
	}
	for _, m := range lock.Modules {
		fmt.Fprintf(h, "%s@%d#%d\x00", m.ID, m.Revision, m.Contract)
	}
	h.Write([]byte(lock.RegistryCommit))
	return hex.EncodeToString(h.Sum(nil))
}

// GenerateAll renders every registry-owned output for the resolved graph. It
// is a pure function of (modulePath, lock, graph): identical inputs always
// produce byte-identical outputs, and the file list is sorted by path.
func GenerateAll(ctx context.Context, modulePath string, lock Lock, graph []Manifest) ([]GeneratedFile, error) {
	// Most emitters produce one file. A few produce a set whose size is itself
	// declared data — one catalog per locale a module translates into — so the
	// contract is a slice rather than a fixed list of emitter names.
	emitters := []struct {
		name string
		fn   func(context.Context, string, Lock, []Manifest) ([]GeneratedFile, error)
	}{
		{"bootstrap", one(emitBootstrapRegistry)},
		{"testhost", one(emitTestHostRegistry)},
		{"routes", one(emitRoutesRegistry)},
		{"chrome", one(emitChromeRegistry)},
		{"settings_nav", one(emitSettingsNavigationRegistry)},
		{"shell_slots", one(emitShellSlotsRegistry)},
		{"locales", one(emitLocalesRegistry)},
		{"catalogs", emitCatalogRegistries},
		{"openapi", one(emitOpenAPIRegistry)},
		{"queries", one(emitQueriesRegistry)},
		{"static", one(emitStaticRegistry)},
		{"ui_components", one(emitUIComponentsRegistry)},
		{"ui_metadata", one(emitUIComponentRegistry)},
		{"ui_reference", one(emitUIReferenceRegistry)},
		{"alpine_fragments", one(emitAlpineFragments)},
		{"engines", one(emitEngineRegistry)},
		{"styles", one(emitStylesRegistry)},
		{"content", one(emitContentRegistry)},
		{"config", one(emitConfigRegistry)},
		{"env-example", one(emitEnvExample)},
		{"config-reference", one(emitConfigReference)},
		{"module-reference", one(emitModuleReference)},
		{"component-reference", one(emitComponentReference)},
		{"jobs", one(emitJobsRegistry)},
		{"data-lifecycle", one(emitDataLifecycleRegistry)},
		{"seeds", one(emitSeedRegistry)},
		{"personas", one(emitPersonasRegistry)},
		{"scenarios", one(emitScenarioRegistry)},
		{"surfaces", one(emitVisualSurfaces)},
	}
	files := make([]GeneratedFile, 0, len(emitters))
	for _, emitter := range emitters {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		emitted, err := emitter.fn(ctx, modulePath, lock, graph)
		if err != nil {
			return nil, fmt.Errorf("generate %s: %w", emitter.name, err)
		}
		for i := range emitted {
			file := emitted[i]
			if !isGeneratedOutput(file.Path) {
				return nil, fmt.Errorf("emitter %s produced non-generated path %s", emitter.name, file.Path)
			}
			formatted, err := formatGo(&file)
			if err != nil {
				return nil, fmt.Errorf("generate %s: %w", emitter.name, err)
			}
			files = append(files, *formatted)
		}
	}
	sort.Slice(files, func(i, j int) bool { return files[i].Path < files[j].Path })
	return files, nil
}

// one adapts a single-file emitter to the slice contract. A nil file means the
// emitter had nothing to produce, which is legal.
func one(fn func(context.Context, string, Lock, []Manifest) (*GeneratedFile, error)) func(context.Context, string, Lock, []Manifest) ([]GeneratedFile, error) {
	return func(ctx context.Context, modulePath string, lock Lock, graph []Manifest) ([]GeneratedFile, error) {
		file, err := fn(ctx, modulePath, lock, graph)
		if err != nil || file == nil {
			return nil, err
		}
		return []GeneratedFile{*file}, nil
	}
}

// qualifyPackage turns a module-relative package path from a manifest into an
// import path in the target module. Manifests never carry absolute import paths:
// a derivative's Go module path differs from the canonical one, so an absolute
// path baked into distributed data would not compile once installed.
func qualifyPackage(modulePath, pkg string) string {
	return modulePath + "/" + strings.Trim(pkg, "/")
}

// resolveTypeImport resolves a declared provide-type import. An external module
// path is domain-qualified (its first segment contains a dot) and is used
// verbatim; anything else is module-relative and qualified against the target
// module, so a derivative imports its own copy rather than the upstream one.
func resolveTypeImport(modulePath, declared string) string {
	trimmed := strings.Trim(declared, "/")
	first := trimmed
	if i := strings.Index(trimmed, "/"); i >= 0 {
		first = trimmed[:i]
	}
	if strings.Contains(first, ".") {
		return trimmed
	}
	return qualifyPackage(modulePath, trimmed)
}

// bootstrapFixedImports are the packages the generated bootstrap always imports.
// A declared type import naming one of these is skipped rather than resolved,
// because a dotless stdlib path is indistinguishable from a module-relative one.
var bootstrapFixedImports = map[string]struct{}{
	"context":  {},
	"errors":   {},
	"fmt":      {},
	"net/http": {},
}

// DefaultJobAttempts mirrors jobs.DefaultMaxAttempts and the jobs.max_attempts
// column default. A declaration that omits a budget gets this.
const DefaultJobAttempts = 8

// httpHandlerCapability is the one structurally special capability: the module
// providing it is what the runtime serves.
const httpHandlerCapability = "http.handler"

// capabilityField turns a capability name into the exported Runtime field that
// carries it. Capabilities are globally unique (the namespace preflight enforces
// it), so deriving the field from the capability — not from the module's own
// field name — keeps two modules that both provide a "Client" from colliding.
func capabilityField(capability string) string {
	var b strings.Builder
	for _, segment := range strings.FieldsFunc(capability, func(r rune) bool {
		return r == '.' || r == '-' || r == '_' || r == '/'
	}) {
		if initialism, ok := goInitialisms[segment]; ok {
			b.WriteString(initialism)
			continue
		}
		b.WriteString(strings.ToUpper(segment[:1]))
		b.WriteString(segment[1:])
	}
	return b.String()
}

// goInitialisms keeps generated field names idiomatic. Go spells initialisms in
// one case, and so does the rest of this codebase (AppURL, LLMAPIKey), so the
// generator must not emit HttpHandler or LlmCompleter.
var goInitialisms = map[string]string{
	"api":   "API",
	"csv":   "CSV",
	"db":    "DB",
	"dsn":   "DSN",
	"html":  "HTML",
	"http":  "HTTP",
	"https": "HTTPS",
	"id":    "ID",
	"json":  "JSON",
	"llm":   "LLM",
	"sql":   "SQL",
	"ui":    "UI",
	"url":   "URL",
	"uuid":  "UUID",
	"yaml":  "YAML",
}

func goImportName(pkg string) string {
	base := pkg
	if i := strings.LastIndex(pkg, "/"); i >= 0 {
		base = pkg[i+1:]
	}
	if i := strings.LastIndex(base, "-"); i >= 0 {
		base = base[:i]
	}
	return base
}

// goVar returns a deterministic Go variable name for a module ID.
func goVar(id string) string {
	name := strings.ReplaceAll(id, "/", "_")
	name = strings.ReplaceAll(name, "-", "_")
	return name + "Module"
}

func goString(s string) string {
	return fmt.Sprintf("%q", s)
}

// orderedModules returns the graph modules in lock topological order.
func orderedModules(lock Lock, graph []Manifest) []Manifest {
	byID := make(map[string]Manifest, len(graph))
	for _, m := range graph {
		byID[m.ID] = m
	}
	ordered := make([]Manifest, 0, len(lock.Order))
	for _, id := range lock.Order {
		if m, ok := byID[id]; ok {
			ordered = append(ordered, m)
		}
	}
	return ordered
}

// collectRootNeeds returns needs whose capability is not provided by any
// module in the graph; these are ambient values supplied by Options.
func collectRootNeeds(lock Lock, graph []Manifest) []RuntimeNeed {
	provided := make(map[string]bool)
	for _, m := range orderedModules(lock, graph) {
		if m.Runtime.System != nil {
			for _, p := range m.Runtime.System.Provides {
				provided[p.Capability] = true
			}
		}
	}
	seen := make(map[string]bool)
	needs := make([]RuntimeNeed, 0)
	for _, m := range orderedModules(lock, graph) {
		if m.Runtime.System == nil {
			continue
		}
		for _, n := range m.Runtime.System.Needs {
			if provided[n.Capability] || seen[n.Field] {
				continue
			}
			seen[n.Field] = true
			needs = append(needs, n)
		}
	}
	return needs
}

func isRootCapability(rootNeeds []RuntimeNeed, need RuntimeNeed) bool {
	for _, n := range rootNeeds {
		if n.Capability == need.Capability && n.Field == need.Field {
			return true
		}
	}
	return false
}

// emitBootstrapRegistry renders internal/modules/bootstrap_registry_gen.go,
// the only file that imports every selected system module. It generates direct
// constructor calls in topological order so an incorrect manifest declaration
// becomes a compile error on a named generated line.
func emitBootstrapRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	modules := orderedModules(lock, graph)
	rootNeeds := collectRootNeeds(lock, graph)
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package modules\n\n")
	needsErrors := false
	for _, m := range modules {
		if m.Runtime.System != nil && m.Runtime.System.Stop {
			needsErrors = true
		}
	}
	b.WriteString("import (\n")
	b.WriteString("\t\"context\"\n")
	if needsErrors {
		b.WriteString("\t\"errors\"\n")
	}
	b.WriteString("\t\"fmt\"\n")
	b.WriteString("\t\"net/http\"\n")
	b.WriteString("\n")
	imports := []string{"\tapphost \"" + modulePath + "/internal/apphost\"\n"}
	seenImports := make(map[string]struct{})
	for _, m := range modules {
		if m.Runtime.System == nil || m.Runtime.System.Package == "" {
			continue
		}
		qualified := qualifyPackage(modulePath, m.Runtime.System.Package)
		if _, ok := seenImports[qualified]; !ok {
			seenImports[qualified] = struct{}{}
			imports = append(imports, "\t"+goImportName(qualified)+" \""+qualified+"\"\n")
		}
		for _, extra := range m.Runtime.System.TypeImports {
			if _, fixed := bootstrapFixedImports[strings.Trim(extra, "/")]; fixed {
				// Already imported unconditionally below; resolving it would also
				// mistake a dotless stdlib path for a module-relative one.
				continue
			}
			resolved := resolveTypeImport(modulePath, extra)
			if _, ok := seenImports[resolved]; ok {
				continue
			}
			seenImports[resolved] = struct{}{}
			imports = append(imports, "\t"+goImportName(resolved)+" \""+resolved+"\"\n")
		}
	}
	sort.Strings(imports)
	for _, line := range imports {
		b.WriteString(line)
	}
	b.WriteString(")\n\n")

	b.WriteString("// Options carries the ambient values the selected closure boots with.\n")
	b.WriteString("type Options struct {\n")
	for _, need := range rootNeeds {
		fmt.Fprintf(&b, "\t%s %s\n", need.Field, need.Type)
	}
	b.WriteString("}\n\n")
	b.WriteString("// Runtime is the booted module closure. Every capability the selected\n")
	b.WriteString("// graph provides is reachable here, so consumers take typed values rather\n")
	b.WriteString("// than reconstructing providers.\n")
	// One capability is structural: whichever module provides http.handler is
	// what Handler() returns, so the runtime composes a servable handler instead
	// of carrying a field nothing ever assigns.
	handlerField := ""
	for _, m := range modules {
		if m.Runtime.System == nil {
			continue
		}
		for _, provide := range m.Runtime.System.Provides {
			if provide.Capability == httpHandlerCapability {
				handlerField = capabilityField(provide.Capability)
			}
		}
	}

	b.WriteString("type Runtime struct {\n")
	b.WriteString("\tstart []func(context.Context) error\n")
	b.WriteString("\tstop  []apphost.Stop\n")
	provided := make([]string, 0)
	for _, m := range modules {
		if m.Runtime.System == nil {
			continue
		}
		for _, provide := range m.Runtime.System.Provides {
			field := capabilityField(provide.Capability)
			if !validIdentifier(field) {
				return nil, fmt.Errorf("module %s: capability %q does not yield a Go field", m.ID, provide.Capability)
			}
			provided = append(provided, fmt.Sprintf("\t%s %s\n", field, provide.Type))
		}
	}
	sort.Strings(provided)
	if len(provided) > 0 {
		b.WriteString("\n")
		for _, line := range provided {
			b.WriteString(line)
		}
	}
	b.WriteString("}\n\n")

	b.WriteString("// Boot validates the selected closure and constructs typed dependencies in\n")
	b.WriteString("// stable topological order, then starts long-lived services.\n")
	b.WriteString("func Boot(ctx context.Context, h apphost.Host, opts Options) (*Runtime, error) {\n")
	b.WriteString("\tr := &Runtime{}\n")
	b.WriteString("\t_ = h\n")
	provider := make(map[string]string)
	stoppers := make([]string, 0)
	starters := make([]string, 0)
	for _, m := range modules {
		sys := m.Runtime.System
		if sys == nil || sys.Package == "" || sys.Constructor == "" {
			continue
		}
		if err := validateIdentifiers(sys); err != nil {
			return nil, fmt.Errorf("module %s: %w", m.ID, err)
		}
		pkg := goImportName(qualifyPackage(modulePath, sys.Package))
		varName := goVar(m.ID)
		target := varName
		if len(sys.Provides) == 0 && !sys.Stop && !sys.Start {
			// Nothing consumes the result, so binding it would not compile.
			target = "_"
		}
		fmt.Fprintf(&b, "\t%s, err := %s.%s(ctx, h, %s.Deps{\n", target, pkg, sys.Constructor, pkg)
		for _, need := range sys.Needs {
			if !validIdentifier(need.Field) {
				return nil, fmt.Errorf("module %s: invalid need field %q", m.ID, need.Field)
			}
			if expr, ok := provider[need.Capability]; ok {
				fmt.Fprintf(&b, "\t\t%s: %s,\n", need.Field, expr)
				continue
			}
			if isRootCapability(rootNeeds, need) {
				fmt.Fprintf(&b, "\t\t%s: opts.%s,\n", need.Field, need.Field)
				continue
			}
			if need.Optional {
				continue
			}
			return nil, fmt.Errorf("module %s: no module provides capability %q for need %s", m.ID, need.Capability, need.Field)
		}
		b.WriteString("\t})\n")
		b.WriteString("\tif err != nil {\n")
		fmt.Fprintf(&b, "\t\treturn nil, fmt.Errorf(\"boot %s: %%w\", err)\n", goString(m.ID)[1:len(goString(m.ID))-1])
		b.WriteString("\t}\n")
		for _, provide := range sys.Provides {
			if !validIdentifier(provide.Field) {
				return nil, fmt.Errorf("module %s: invalid provide field %q", m.ID, provide.Field)
			}
			field := capabilityField(provide.Capability)
			fmt.Fprintf(&b, "\tr.%s = %s.%s\n", field, varName, provide.Field)
			provider[provide.Capability] = "r." + field
		}
		if sys.Start {
			fmt.Fprintf(&b, "\tr.start = append(r.start, %s.Start)\n", varName)
			starters = append(starters, varName)
		}
		if sys.Stop {
			fmt.Fprintf(&b, "\tr.stop = append(r.stop, %s.Stop)\n", varName)
			stoppers = append(stoppers, varName)
		}
	}
	b.WriteString("\treturn r, nil\n")
	b.WriteString("}\n\n")

	b.WriteString("// Handler returns the composed HTTP handler.\n")
	if handlerField == "" {
		b.WriteString("// The selected graph provides none, so there is nothing to serve.\n")
		b.WriteString("func (r *Runtime) Handler() http.Handler { return nil }\n\n")
	} else {
		fmt.Fprintf(&b, "func (r *Runtime) Handler() http.Handler { return r.%s }\n\n", handlerField)
	}
	b.WriteString("// Run starts every long-lived service in dependency order. Each Start must\n")
	b.WriteString("// return promptly — a module owns its own goroutine — so Run hands control back\n")
	b.WriteString("// to the caller that serves traffic.\n")
	if len(starters) == 0 {
		b.WriteString("func (r *Runtime) Run(ctx context.Context) error { return nil }\n\n")
	} else {
		b.WriteString("func (r *Runtime) Run(ctx context.Context) error {\n")
		b.WriteString("\tfor _, start := range r.start {\n")
		b.WriteString("\t\tif err := start(ctx); err != nil {\n")
		b.WriteString("\t\t\treturn err\n")
		b.WriteString("\t\t}\n")
		b.WriteString("\t}\n")
		b.WriteString("\treturn nil\n")
		b.WriteString("}\n\n")
	}
	b.WriteString("// Close stops services in reverse dependency order. Every stop hook runs\n")
	b.WriteString("// even if an earlier one fails, so one stuck service cannot strand the rest;\n")
	b.WriteString("// the joined error reports all of them.\n")
	b.WriteString("func (r *Runtime) Close(ctx context.Context) error {\n")
	if len(stoppers) == 0 {
		b.WriteString("\treturn nil\n")
		b.WriteString("}\n")
	} else {
		b.WriteString("\tvar errs []error\n")
		b.WriteString("\tfor i := len(r.stop) - 1; i >= 0; i-- {\n")
		b.WriteString("\t\tif err := r.stop[i](ctx); err != nil {\n")
		b.WriteString("\t\t\terrs = append(errs, err)\n")
		b.WriteString("\t\t}\n")
		b.WriteString("\t}\n")
		b.WriteString("\treturn errors.Join(errs...)\n")
		b.WriteString("}\n")
	}

	_ = ctx
	return &GeneratedFile{Path: "internal/modules/bootstrap_registry_gen.go", Content: b.String()}, nil
}

func validateIdentifiers(sys *SystemContribution) error {
	if !validPackagePath(sys.Package) {
		return fmt.Errorf("invalid system package path %q", sys.Package)
	}
	if !validIdentifier(sys.Constructor) {
		return fmt.Errorf("invalid system constructor %q", sys.Constructor)
	}
	return nil
}

// emitTestHostRegistry renders internal/modules/testhost_registry_gen.go. It
// exposes a TestHost used by tests to construct a runtime against a fixture
// lock; Boot never reads this table.
func emitTestHostRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	modules := orderedModules(lock, graph)
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package modules\n\n")
	b.WriteString("// testHostModules lists the module IDs a test runtime boots with. Boot never\n")
	b.WriteString("// reads this table; test-only items are addressable only here.\n")
	b.WriteString("var testHostModules = []string{\n")
	for _, m := range modules {
		fmt.Fprintf(&b, "\t%s,\n", goString(m.ID))
	}
	b.WriteString("}\n\n")
	b.WriteString("// TestHost returns the module IDs a test runtime boots with.\n")
	b.WriteString("func TestHost() []string { return append([]string{}, testHostModules...) }\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/modules/testhost_registry_gen.go", Content: b.String()}, nil
}

// emitRoutesRegistry renders internal/web/routes_registry_gen.go from every
// selected RouteContribution, in module topological order then lexical ID.
// hasJanitors reports whether any selected module declares a cleanup sweep.
func hasJanitors(graph []Manifest) bool {
	for _, m := range graph {
		if len(m.Runtime.Janitors) > 0 {
			return true
		}
	}
	return false
}

// routePattern is one concrete method+pattern pair awaiting validation.
type routePattern struct {
	id      string
	module  string
	method  string
	pattern string
}

// route is one concrete registered route: a declaration plus, for a route
// expanded from a content type, the type its handler resolves by id.
type route struct {
	moduleID string
	contrib  RouteContribution
	// contentType is non-empty for a route expanded from a content type
	// declaration; its handler resolves the type by id.
	contentType string
}

// selectedRoutes is every route the router will register, in module order. A
// content type declares public paths, not routes; expanding them here is what
// lets the generator know every pattern and reserved prefix before boot,
// instead of the router walking a registry at startup.
//
// Navigation resolves hrefs against this same set, so a nav link and the route
// it points at can never disagree.
func selectedRoutes(lock Lock, graph []Manifest) []route {
	routes := make([]route, 0)
	for _, m := range orderedModules(lock, graph) {
		for _, r := range m.Runtime.Routes {
			routes = append(routes, route{moduleID: m.ID, contrib: r})
		}
		for _, ct := range m.Runtime.ContentTypes {
			for _, path := range ct.Paths {
				routes = append(routes, route{moduleID: m.ID, contrib: RouteContribution{
					ID: "content." + ct.ID + ".index", Method: "GET", Pattern: path,
					Scope: RoutePublic, Package: ct.Package, Handler: "handleContentIndex",
				}, contentType: ct.ID})
				if ct.Mode != ContentModePages {
					continue
				}
				routes = append(routes, route{moduleID: m.ID, contrib: RouteContribution{
					ID: "content." + ct.ID + ".detail", Method: "GET", Pattern: path + "/{slug}",
					Scope: RoutePublic, Package: ct.Package, Handler: "handleContentDetail",
				}, contentType: ct.ID})
			}
		}
	}
	return routes
}

func emitRoutesRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	routes := selectedRoutes(lock, graph)
	sort.Slice(routes, func(i, j int) bool {
		if routes[i].contrib.Pattern != routes[j].contrib.Pattern {
			return routes[i].contrib.Pattern < routes[j].contrib.Pattern
		}
		if routes[i].contrib.Method != routes[j].contrib.Method {
			return routes[i].contrib.Method < routes[j].contrib.Method
		}
		return routes[i].contrib.ID < routes[j].contrib.ID
	})
	if len(routes) == 0 {
		// Nothing contributes a route, so the project has no reason to define the
		// route type this table would reference.
		return nil, nil
	}

	// Every exemption must carry a reason. A bare bool in a diff is a security
	// decision nobody can review.
	for _, r := range routes {
		if r.contrib.Policy.CSRFExempt && strings.TrimSpace(r.contrib.Policy.CSRFReason) == "" {
			return nil, fmt.Errorf(
				"route %s (%s): csrf_exempt requires csrf_reason", r.contrib.ID, r.moduleID)
		}
	}

	// Validate against a real ServeMux. A conflicting or malformed pattern would
	// otherwise panic on the first matching request, long after this generated
	// file was committed and shipped.
	patterns := make([]routePattern, 0, len(routes))
	for _, r := range routes {
		patterns = append(patterns, routePattern{
			id: r.contrib.ID, module: r.moduleID,
			method: r.contrib.Method, pattern: r.contrib.Pattern,
		})
	}
	if err := validateRoutePatterns(patterns); err != nil {
		return nil, err
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package web\n\n")
	b.WriteString("import \"net/http\"\n\n")
	b.WriteString("// RouteRegistry is the complete set of selected routes. Every pattern is a\n")
	b.WriteString("// concrete string known before boot, so the reserved-prefix, sitemap, policy,\n")
	b.WriteString("// and catch-all decisions are all derived from this one table.\n")
	b.WriteString("var RouteRegistry = []Route{\n")
	for _, r := range routes {
		c := r.contrib
		if !validIdentifier(c.Handler) {
			return nil, fmt.Errorf("route %s: handler %q is not a Go identifier", c.ID, c.Handler)
		}
		if c.Enabled != "" && !validIdentifier(c.Enabled) {
			return nil, fmt.Errorf("route %s: enabled %q is not a Go identifier", c.ID, c.Enabled)
		}
		scope, ok := routeScopeConstant(c.Scope)
		if !ok {
			return nil, fmt.Errorf("route %s: scope %q is not a known scope", c.ID, c.Scope)
		}
		fmt.Fprintf(&b, "\t{\n\t\tID: %s, Method: %s, Pattern: %s,\n",
			goString(c.ID), goString(c.Method), goString(c.Pattern))
		fmt.Fprintf(&b, "\t\tScope: %s,\n", scope)
		fmt.Fprintf(&b, "\t\tPolicy: %s,\n", routePolicyLiteral(c.Policy))
		if r.contentType != "" {
			fmt.Fprintf(&b, "\t\tHandler: func(s *Server) http.Handler { return s.%s(%s) },\n",
				c.Handler, goString(r.contentType))
		} else {
			fmt.Fprintf(&b, "\t\tHandler: func(s *Server) http.Handler { return http.HandlerFunc(s.%s) },\n", c.Handler)
		}
		if c.Enabled != "" {
			fmt.Fprintf(&b, "\t\tEnabled: func(s *Server) bool { return s.%s() },\n", c.Enabled)
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/web/routes_registry_gen.go", Content: b.String()}, nil
}

// routePolicyLiteral renders only the fields that differ from the zero policy,
// so a reader sees the decisions a route actually made.
func routePolicyLiteral(policy RoutePolicy) string {
	parts := make([]string, 0, 7)
	if policy.CSRFExempt {
		parts = append(parts, "CSRFExempt: true")
		parts = append(parts, "CSRFReason: "+goString(policy.CSRFReason))
	}
	if policy.RateExempt {
		parts = append(parts, "RateExempt: true")
	}
	if policy.MaintenanceExempt {
		parts = append(parts, "MaintenanceExempt: true")
	}
	if policy.MaxBodyBytes != 0 {
		parts = append(parts, fmt.Sprintf("MaxBodyBytes: %d", policy.MaxBodyBytes))
	}
	if policy.Idempotent {
		parts = append(parts, "Idempotent: true")
	}
	if policy.AdminWrite {
		parts = append(parts, "AdminWrite: true")
	}
	if len(parts) == 0 {
		return "RoutePolicy{}"
	}
	return "RoutePolicy{" + strings.Join(parts, ", ") + "}"
}

// routeScopeConstant maps a declared scope onto the exported Go constant, so an
// unknown scope is a generation failure rather than an unguarded string.
func routeScopeConstant(scope RouteScope) (string, bool) {
	switch scope {
	case RoutePublic:
		return "ScopePublic", true
	case RouteApp:
		return "ScopeApp", true
	case RouteAdmin:
		return "ScopeAdmin", true
	case RouteAPIRead:
		return "ScopeAPIRead", true
	case RouteAPIWrite:
		return "ScopeAPIWrite", true
	case RouteWebhook:
		return "ScopeWebhook", true
	case RouteStatic:
		return "ScopeStatic", true
	case RouteProbe:
		return "ScopeProbe", true
	case RouteDev:
		return "ScopeDev", true
	}
	return "", false
}

func routeHandlerName(r RouteContribution) string {
	if r.Handler == "" {
		return "noop"
	}
	return r.Handler
}

func routeEnabledName(r RouteContribution) string {
	if r.Enabled == "" {
		return "always"
	}
	return r.Enabled
}

// emitChromeRegistry renders the shell navigation from route-linked
// declarations. Hrefs come from the same route records the router is built
// from, so a nav link cannot point at a route no module registers, and a page
// module carries its own sidebar entry rather than editing a central list.
func emitChromeRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	nav, err := resolveNavigation(lock, graph)
	if err != nil {
		return nil, err
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package templates\n\n")

	for _, area := range []struct {
		area NavArea
		name string
		note string
	}{
		{NavAreaPublic, "PublicNav", "the marketing header"},
		{NavAreaApp, "AppNav", "the application sidebar"},
		{NavAreaAdmin, "AdminNav", "the admin sidebar"},
	} {
		fmt.Fprintf(&b, "// %s is %s, in declared order.\n", area.name, area.note)
		fmt.Fprintf(&b, "var %s = []NavItem{\n", area.name)
		for _, entry := range nav[area.area] {
			b.WriteString("\t" + navItemLiteral(entry) + ",\n")
		}
		b.WriteString("}\n\n")
	}

	// Footer columns keep their declared grouping; a column exists because a
	// module put an entry in it.
	b.WriteString("// FooterColumns are the footer link columns, in declared order.\n")
	b.WriteString("var FooterColumns = []NavColumn{\n")
	for _, group := range footerGroups(nav[NavAreaFooter]) {
		fmt.Fprintf(&b, "\t{TitleKey: %s, Items: []NavItem{\n", goString(group.title))
		for _, entry := range group.entries {
			b.WriteString("\t\t" + navItemLiteral(entry) + ",\n")
		}
		b.WriteString("\t}},\n")
	}
	b.WriteString("}\n\n")

	b.WriteString("// ChromeRegistry is every navigation entry ID in declared order, which is\n")
	b.WriteString("// what a completeness check compares against.\n")
	b.WriteString("var ChromeRegistry = []string{\n")
	for _, area := range []NavArea{NavAreaPublic, NavAreaApp, NavAreaAdmin, NavAreaFooter, NavAreaSettings} {
		for _, entry := range nav[area] {
			fmt.Fprintf(&b, "\t%s,\n", goString(entry.contrib.ID))
		}
	}
	b.WriteString("}\n")

	_ = ctx
	return &GeneratedFile{Path: "internal/web/templates/chrome_registry_gen.go", Content: b.String()}, nil
}

// emitSettingsNavigationRegistry renders the settings tab strip. Tabs keep
// their declared role and flag conditions, evaluated per request, because a tab
// whose page 404s for the viewer is worse than an absent tab.
func emitSettingsNavigationRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	nav, err := resolveNavigation(lock, graph)
	if err != nil {
		return nil, err
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package templates\n\n")
	b.WriteString("// SettingsTab is one settings tab and the conditions under which it is shown.\n")
	b.WriteString("type SettingsTab struct {\n\tItem  NavItem\n\tRoles []string\n\tFlags []string\n}\n\n")
	b.WriteString("// SettingsNavigationRegistry is the declared settings tabs in order. Use\n")
	b.WriteString("// settingsTabs(ctx) to get the subset the current viewer may see.\n")
	b.WriteString("var SettingsNavigationRegistry = []SettingsTab{\n")
	for _, entry := range nav[NavAreaSettings] {
		fmt.Fprintf(&b, "\t{Item: NavItem%s, Roles: %s, Flags: %s},\n",
			navItemLiteral(entry), goStringSlice(entry.contrib.Roles), goStringSlice(entry.contrib.Flags))
	}
	b.WriteString("}\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/web/templates/settings_navigation_registry_gen.go", Content: b.String()}, nil
}

// navEntry is one resolved navigation entry: its declaration plus the href
// resolved from the route table.
type navEntry struct {
	contrib NavigationContribution
	href    string
	module  string
}

func navItemLiteral(e navEntry) string {
	var b strings.Builder
	fmt.Fprintf(&b, "{ID: %s, LabelKey: %s, Href: %s",
		goString(e.contrib.ID), goString(e.contrib.LabelKey), goString(e.href))
	// Match is omitted when it equals the href, which is the common leaf case;
	// the accessor already falls back to Href.
	if e.contrib.Match != "" && e.contrib.Match != e.href {
		fmt.Fprintf(&b, ", Match: %s", goString(e.contrib.Match))
	}
	b.WriteString("}")
	return b.String()
}

func goStringSlice(values []string) string {
	if len(values) == 0 {
		return "nil"
	}
	parts := make([]string, 0, len(values))
	for _, v := range values {
		parts = append(parts, goString(v))
	}
	return "[]string{" + strings.Join(parts, ", ") + "}"
}

type footerGroup struct {
	title   string
	entries []navEntry
}

// footerGroups preserves the order columns are first mentioned in, so a module
// adding an entry to an existing column does not reorder the footer.
func footerGroups(entries []navEntry) []footerGroup {
	var groups []footerGroup
	index := make(map[string]int)
	for _, entry := range entries {
		title := entry.contrib.Group
		if _, ok := index[title]; !ok {
			index[title] = len(groups)
			groups = append(groups, footerGroup{title: title})
		}
		at := index[title]
		groups[at].entries = append(groups[at].entries, entry)
	}
	return groups
}

// resolveNavigation validates every declaration and orders each area. Ordering
// is a topological sort over the declared before/after edges with manifest
// order as the tiebreak, so the result is deterministic and a cycle is an
// error rather than whichever order a map happened to produce.
func resolveNavigation(lock Lock, graph []Manifest) (map[NavArea][]navEntry, error) {
	routes := make(map[string]RouteContribution)
	for _, r := range selectedRoutes(lock, graph) {
		routes[r.contrib.ID] = r.contrib
	}

	byArea := make(map[NavArea][]navEntry)
	seen := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, n := range m.Runtime.Navigation {
			if previous, clash := seen[n.ID]; clash {
				return nil, fmt.Errorf("navigation entry %q is declared by both %s and %s", n.ID, previous, m.ID)
			}
			seen[n.ID] = m.ID

			switch {
			case n.RouteID != "" && n.Href != "":
				return nil, fmt.Errorf("navigation entry %s declares both a route and an href", n.ID)
			case n.RouteID == "" && n.Href == "":
				return nil, fmt.Errorf("navigation entry %s declares no target", n.ID)
			}
			href := n.Href
			if n.RouteID != "" {
				route, ok := routes[n.RouteID]
				if !ok {
					return nil, fmt.Errorf("navigation entry %s points at unregistered route %q", n.ID, n.RouteID)
				}
				if route.Method != http.MethodGet {
					return nil, fmt.Errorf("navigation entry %s points at %s %s, which a link cannot follow",
						n.ID, route.Method, route.Pattern)
				}
				href = route.Pattern
			}
			if n.LabelKey == "" {
				return nil, fmt.Errorf("navigation entry %s has no label key", n.ID)
			}
			if n.Area == NavAreaFooter && n.Group == "" {
				return nil, fmt.Errorf("footer entry %s declares no column", n.ID)
			}
			if n.Area != NavAreaFooter && n.Group != "" {
				return nil, fmt.Errorf("navigation entry %s declares a footer column outside the footer", n.ID)
			}
			// A condition the runtime does not recognise evaluates as unmet, so a
			// typo would silently hide an entry. Refuse it here instead.
			for _, flag := range n.Flags {
				if flag != "webhooks" {
					return nil, fmt.Errorf("navigation entry %s gates on unknown flag %q", n.ID, flag)
				}
			}
			for _, role := range n.Roles {
				if role != "staff" && role != "admin" {
					return nil, fmt.Errorf("navigation entry %s gates on unknown role %q", n.ID, role)
				}
			}
			byArea[n.Area] = append(byArea[n.Area], navEntry{contrib: n, href: href, module: m.ID})
		}
	}

	for area, entries := range byArea {
		ordered, err := orderNavEntries(entries)
		if err != nil {
			return nil, fmt.Errorf("navigation area %s: %w", area, err)
		}
		byArea[area] = ordered
	}
	return byArea, nil
}

// orderNavEntries topologically sorts one area. Declaration order is the
// tiebreak, so an area with no constraints keeps the order modules were
// installed in.
func orderNavEntries(entries []navEntry) ([]navEntry, error) {
	position := make(map[string]int, len(entries))
	for i, e := range entries {
		position[e.contrib.ID] = i
	}

	// after[x] holds the entries that must precede x.
	predecessors := make(map[string]map[string]bool, len(entries))
	for _, e := range entries {
		if predecessors[e.contrib.ID] == nil {
			predecessors[e.contrib.ID] = make(map[string]bool)
		}
	}
	edge := func(earlier, later string) error {
		if _, ok := position[later]; !ok {
			return fmt.Errorf("entry %q orders against unknown entry %q", earlier, later)
		}
		if predecessors[later] == nil {
			predecessors[later] = make(map[string]bool)
		}
		predecessors[later][earlier] = true
		return nil
	}
	for _, e := range entries {
		for _, other := range e.contrib.After {
			if _, ok := position[other]; !ok {
				return nil, fmt.Errorf("entry %q declares after %q, which is not in this area", e.contrib.ID, other)
			}
			if err := edge(other, e.contrib.ID); err != nil {
				return nil, err
			}
		}
		for _, other := range e.contrib.Before {
			if _, ok := position[other]; !ok {
				return nil, fmt.Errorf("entry %q declares before %q, which is not in this area", e.contrib.ID, other)
			}
			if err := edge(e.contrib.ID, other); err != nil {
				return nil, err
			}
		}
	}

	remaining := make(map[string]bool, len(entries))
	for _, e := range entries {
		remaining[e.contrib.ID] = true
	}
	out := make([]navEntry, 0, len(entries))
	for len(out) < len(entries) {
		// Lowest declaration index whose predecessors are all placed: a stable
		// choice, so the same declarations always emit the same order.
		best := -1
		for i, e := range entries {
			if !remaining[e.contrib.ID] {
				continue
			}
			ready := true
			for pred := range predecessors[e.contrib.ID] {
				if remaining[pred] {
					ready = false
					break
				}
			}
			if ready && (best == -1 || i < best) {
				best = i
			}
		}
		if best == -1 {
			var stuck []string
			for id := range remaining {
				stuck = append(stuck, id)
			}
			sort.Strings(stuck)
			return nil, fmt.Errorf("ordering cycle among %s", strings.Join(stuck, ", "))
		}
		out = append(out, entries[best])
		delete(remaining, entries[best].contrib.ID)
	}
	return out, nil
}

func emitShellSlotsRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package templates\n\n")
	b.WriteString("// ShellSlotsRegistry lists shell slot contributions by slot name.\n")
	b.WriteString("var ShellSlotsRegistry = map[string][]string{\n")
	bySlot := make(map[string][]string)
	slots := make([]string, 0)
	for _, m := range orderedModules(lock, graph) {
		for _, s := range m.Runtime.Slots {
			key := string(s.Slot)
			if _, seen := bySlot[key]; !seen {
				slots = append(slots, key)
			}
			bySlot[key] = append(bySlot[key], s.ID)
		}
	}
	sort.Strings(slots)
	for _, slot := range slots {
		fmt.Fprintf(&b, "\t%s: []string{\n", goString(slot))
		for _, id := range bySlot[slot] {
			fmt.Fprintf(&b, "\t\t%s,\n", goString(id))
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/web/templates/shell_slots_registry_gen.go", Content: b.String()}, nil
}

// emitLocalesRegistry renders the supported locales from what modules actually
// translate. The switcher cannot offer a language nothing is translated into,
// and the matcher cannot resolve a request to one either.
func emitLocalesRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	declared, err := declaredLocales(lock, graph)
	if err != nil {
		return nil, err
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package i18n\n\n")
	b.WriteString("import \"golang.org/x/text/language\"\n\n")
	b.WriteString("// Locale is one supported language: its switcher code, its matcher tag, and\n")
	b.WriteString("// the label shown in the switcher.\n")
	b.WriteString("type Locale struct {\n\tCode  string\n\tTag   language.Tag\n\tLabel string\n}\n\n")
	b.WriteString("// Locales are the supported languages in display order, derived from the\n")
	b.WriteString("// locales installed modules declare. The first is the default.\n")
	b.WriteString("var Locales = []Locale{\n")
	for _, locale := range declared.locales {
		fmt.Fprintf(&b, "\t{Code: %s, Tag: %s, Label: %s},\n",
			goString(locale), languageExpr(locale), goString(localeLabel(locale)))
	}
	b.WriteString("}\n\n")
	b.WriteString("// CatalogKeys is every key the installed modules declare, sorted. Generation\n")
	b.WriteString("// already guarantees each key exists in every locale, so this is the inventory\n")
	b.WriteString("// callers compare against rather than scraping catalog source text.\n")
	b.WriteString("var CatalogKeys = []string{\n")
	for _, key := range declared.keys {
		fmt.Fprintf(&b, "\t%s,\n", goString(key))
	}
	b.WriteString("}\n\n")
	b.WriteString("// LocaleRegistry lists the modules that own locale entries.\n")
	b.WriteString("var LocaleRegistry = []string{\n")
	owners := make(map[string]bool)
	for _, m := range orderedModules(lock, graph) {
		if len(m.Locales) > 0 && !owners[m.ID] {
			owners[m.ID] = true
			fmt.Fprintf(&b, "\t%s,\n", goString(m.ID))
		}
	}
	b.WriteString("}\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/i18n/locales_registry_gen.go", Content: b.String()}, nil
}

// localeLabel is the switcher label, written in the language it selects — a
// reader looking for their own language recognises it, not its English name.
func localeLabel(locale string) string {
	switch locale {
	case "en":
		return "English"
	case "es":
		return "Espa\u00f1ol"
	default:
		return locale
	}
}

func emitCatalogRegistries(ctx context.Context, modulePath string, lock Lock, graph []Manifest) ([]GeneratedFile, error) {
	declared, err := declaredLocales(lock, graph)
	if err != nil {
		return nil, err
	}
	files := make([]GeneratedFile, 0, len(declared.locales))
	for _, locale := range declared.locales {
		var b strings.Builder
		b.WriteString(genHeader(modulePath, lock))
		b.WriteString("package i18n\n\n")
		b.WriteString("import (\n\t\"golang.org/x/text/language\"\n\t\"golang.org/x/text/message\"\n)\n\n")
		fmt.Fprintf(&b, "// The %s catalog. Every entry is owned by exactly one module, and every key\n", locale)
		b.WriteString("// exists in every declared locale, so a missing translation is a generation\n")
		b.WriteString("// failure rather than a raw key rendered at a user.\n")
		b.WriteString("func init() {\n")
		for _, key := range declared.keys {
			fmt.Fprintf(&b, "\tmessage.SetString(%s, %s, %s)\n",
				languageExpr(locale), goString(key), goString(declared.values[locale][key]))
		}
		b.WriteString("}\n")
		files = append(files, GeneratedFile{
			Path:    "internal/i18n/catalog_" + locale + "_registry_gen.go",
			Content: b.String(),
		})
	}
	_ = ctx
	return files, nil
}

// localeSet is the validated union of every module's locale declarations.
type localeSet struct {
	locales []string
	keys    []string
	values  map[string]map[string]string
	owner   map[string]string
}

// declaredLocales merges module locale records and refuses the three ways a
// catalog goes wrong: two owners for a key, a key missing from a locale, and
// format placeholders that differ between locales.
func declaredLocales(lock Lock, graph []Manifest) (localeSet, error) {
	out := localeSet{
		values: make(map[string]map[string]string),
		owner:  make(map[string]string),
	}
	keySeen := make(map[string]bool)
	for _, m := range orderedModules(lock, graph) {
		for _, locale := range sortedKeys(m.Locales) {
			if !validLocaleCode(locale) {
				return localeSet{}, fmt.Errorf("module %s: locale %q is not a supported code", m.ID, locale)
			}
			if _, seen := out.values[locale]; !seen {
				out.values[locale] = make(map[string]string)
				out.locales = append(out.locales, locale)
			}
			for _, key := range sortedKeys(m.Locales[locale]) {
				if previous, clash := out.owner[key+"\x00"+locale]; clash {
					return localeSet{}, fmt.Errorf("i18n key %q (%s) is declared by both %s and %s",
						key, locale, previous, m.ID)
				}
				out.owner[key+"\x00"+locale] = m.ID
				out.values[locale][key] = m.Locales[locale][key]
				if !keySeen[key] {
					keySeen[key] = true
					out.keys = append(out.keys, key)
				}
			}
		}
	}
	sort.Strings(out.locales)
	sort.Strings(out.keys)

	for _, key := range out.keys {
		var reference, referenceLocale string
		for _, locale := range out.locales {
			value, ok := out.values[locale][key]
			if !ok {
				return localeSet{}, fmt.Errorf("i18n key %q has no %s translation", key, locale)
			}
			verbs := formatVerbs(value)
			if referenceLocale == "" {
				reference, referenceLocale = verbs, locale
				continue
			}
			if verbs != reference {
				return localeSet{}, fmt.Errorf(
					"i18n key %q formats %s as %q in %s but %q in %s",
					key, "arguments", verbs, locale, reference, referenceLocale)
			}
		}
	}
	return out, nil
}

// formatVerbs is the ordered format verbs in a catalog value. Two locales must
// agree exactly: the same arguments, in the same order, formatted the same way,
// or one language formats wrongly at runtime.
func formatVerbs(value string) string {
	var verbs []string
	for i := 0; i < len(value); i++ {
		if value[i] != '%' || i+1 >= len(value) {
			continue
		}
		next := value[i+1]
		if next == '%' {
			i++
			continue
		}
		// Skip flags, width, and precision so "%d" and "%3d" are the same argument.
		j := i + 1
		for j < len(value) && strings.ContainsRune("+-# 0123456789.*[]", rune(value[j])) {
			j++
		}
		if j < len(value) {
			verbs = append(verbs, string(value[j]))
			i = j
		}
	}
	return strings.Join(verbs, ",")
}

// validLocaleCode keeps a typo from becoming a silent third catalog.
func validLocaleCode(code string) bool {
	if len(code) != 2 {
		return false
	}
	for i := 0; i < len(code); i++ {
		if code[i] < 'a' || code[i] > 'z' {
			return false
		}
	}
	return true
}

// languageExpr maps a locale code to its golang.org/x/text tag expression.
func languageExpr(locale string) string {
	switch locale {
	case "en":
		return "language.English"
	case "es":
		return "language.Spanish"
	default:
		return fmt.Sprintf("language.MustParse(%s)", goString(locale))
	}
}

// sortedKeys is a deterministic iteration order over a string-keyed map.
func sortedKeys[V any](m map[string]V) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// emitOpenAPIRegistry merges the module-owned contract fragments into one
// OpenAPI 3.1 document. Operations are keyed by route id and every API route
// must have exactly one, so the documented surface and the served surface are
// the same list by construction rather than by a test that notices later.
//
// Security and the idempotency parameter are derived from each route's declared
// scope and policy. Restating them in a fragment would let the document
// disagree with what middleware actually enforces, which is worse than having
// no document.
func emitOpenAPIRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	document, err := buildOpenAPIDocument(lock, graph)
	if err != nil {
		return nil, err
	}
	if document == nil {
		return nil, nil
	}

	body, err := yaml.Marshal(document)
	if err != nil {
		return nil, fmt.Errorf("encode openapi: %w", err)
	}
	var b strings.Builder
	b.WriteString("# Code generated by ggg sync; DO NOT EDIT.\n")
	b.WriteString("# Edit the declaring module's manifest instead.\n")
	fmt.Fprintf(&b, "# index: %s\n", indexSHA(lock))
	b.Write(body)
	_ = ctx
	_ = modulePath
	return &GeneratedFile{Path: "internal/api/openapi_registry_gen.yaml", Content: b.String()}, nil
}

// bearerSchemeName is the security scheme every authenticated API route uses.
// The document declares it once; routes reference it with their declared scope.
const bearerSchemeName = "bearerAuth"

// The generated idempotency parameter and the reference operations use.
const (
	idempotencyComponentID   = "IdempotencyKey"
	idempotencyParameterName = "Idempotency-Key"
	idempotencyParameterRef  = "#/components/parameters/" + idempotencyComponentID
)

func buildOpenAPIDocument(lock Lock, graph []Manifest) (map[string]any, error) {
	// Routes first: the document is derived from them, not the reverse. The API
	// surface is every route under /api/, including the deliberately
	// unauthenticated contract document itself — a client fetches that before it
	// holds a token, and it still has to be documented.
	apiRoutes := make(map[string]route)
	for _, r := range selectedRoutes(lock, graph) {
		if strings.HasPrefix(r.contrib.Pattern, "/api/") {
			apiRoutes[r.contrib.ID] = r
		}
	}

	document := map[string]any{"openapi": "3.1.0"}
	components := map[string]any{}
	schemaIDs := make(map[string]map[string]string)
	tags := make([]any, 0)
	tagOwner := make(map[string]string)
	paths := map[string]any{}
	operationOwner := make(map[string]string)
	documented := make(map[string]string)
	infoOwner, serversOwner := "", ""
	contributed := false

	for _, m := range orderedModules(lock, graph) {
		api := m.OpenAPI
		if api == nil {
			continue
		}
		contributed = true

		if len(api.Info) > 0 {
			if infoOwner != "" {
				return nil, fmt.Errorf("openapi info is declared by both %s and %s", infoOwner, m.ID)
			}
			infoOwner = m.ID
			value, err := decodeJSON(api.Info)
			if err != nil {
				return nil, fmt.Errorf("module %s openapi info: %w", m.ID, err)
			}
			document["info"] = value
		}
		if len(api.Servers) > 0 {
			if serversOwner != "" {
				return nil, fmt.Errorf("openapi servers are declared by both %s and %s", serversOwner, m.ID)
			}
			serversOwner = m.ID
			value, err := decodeJSON(api.Servers)
			if err != nil {
				return nil, fmt.Errorf("module %s openapi servers: %w", m.ID, err)
			}
			document["servers"] = value
		}
		for _, tag := range api.Tags {
			if previous, clash := tagOwner[tag.Name]; clash {
				return nil, fmt.Errorf("openapi tag %q is declared by both %s and %s", tag.Name, previous, m.ID)
			}
			tagOwner[tag.Name] = m.ID
			tags = append(tags, map[string]any{"name": tag.Name, "description": tag.Description})
		}

		for _, section := range sortedKeys(api.Components) {
			if schemaIDs[section] == nil {
				schemaIDs[section] = make(map[string]string)
			}
			existing, _ := components[section].(map[string]any)
			if existing == nil {
				existing = map[string]any{}
			}
			for _, id := range sortedKeys(api.Components[section]) {
				if previous, clash := schemaIDs[section][id]; clash {
					return nil, fmt.Errorf("openapi %s/%s is declared by both %s and %s", section, id, previous, m.ID)
				}
				schemaIDs[section][id] = m.ID
				value, err := decodeJSON(api.Components[section][id])
				if err != nil {
					return nil, fmt.Errorf("module %s openapi %s/%s: %w", m.ID, section, id, err)
				}
				existing[id] = value
			}
			components[section] = existing
		}

		for _, op := range api.Operations {
			r, ok := apiRoutes[op.RouteID]
			if !ok {
				return nil, fmt.Errorf("openapi operation %q describes route %q, which no module serves as an API route",
					op.OperationID, op.RouteID)
			}
			if previous, clash := documented[op.RouteID]; clash {
				return nil, fmt.Errorf("route %s is documented by both %s and %s", op.RouteID, previous, m.ID)
			}
			documented[op.RouteID] = m.ID
			if op.OperationID == "" {
				return nil, fmt.Errorf("openapi operation for %s has no operationId", op.RouteID)
			}
			if previous, clash := operationOwner[op.OperationID]; clash {
				return nil, fmt.Errorf("openapi operationId %q is used by both %s and %s", op.OperationID, previous, m.ID)
			}
			operationOwner[op.OperationID] = m.ID

			built, err := buildOperation(m.ID, op, r.contrib)
			if err != nil {
				return nil, err
			}
			byMethod, _ := paths[r.contrib.Pattern].(map[string]any)
			if byMethod == nil {
				byMethod = map[string]any{}
			}
			byMethod[strings.ToLower(r.contrib.Method)] = built
			paths[r.contrib.Pattern] = byMethod

			for _, tag := range op.Tags {
				if _, known := tagOwner[tag]; !known {
					return nil, fmt.Errorf("openapi operation %s uses undeclared tag %q", op.OperationID, tag)
				}
			}
		}
	}

	if !contributed {
		return nil, nil
	}
	if infoOwner == "" {
		return nil, errors.New("openapi document has no info block; exactly one module must declare it")
	}

	// An API route with no operation ships an undocumented endpoint.
	for id, r := range apiRoutes {
		if _, ok := documented[id]; !ok {
			return nil, fmt.Errorf("API route %s (%s %s) has no openapi operation",
				id, r.contrib.Method, r.contrib.Pattern)
		}
	}

	// The security scheme belongs to the document, not to a module: every
	// authenticated route references the same one.
	securitySchemes, _ := components["securitySchemes"].(map[string]any)
	if securitySchemes == nil {
		securitySchemes = map[string]any{}
	}
	if _, taken := securitySchemes[bearerSchemeName]; taken {
		return nil, fmt.Errorf("openapi securityScheme %q is generated and must not be declared", bearerSchemeName)
	}
	securitySchemes[bearerSchemeName] = map[string]any{
		"type":         "http",
		"scheme":       "bearer",
		"bearerFormat": "opaque",
		"description": "Bearer token minted at /app/settings/api. Scope read satisfies read " +
			"operations, write satisfies both. The token determines the organization.",
	}
	components["securitySchemes"] = securitySchemes

	// The idempotency parameter is generated alongside the routes that reference
	// it, so its description cannot drift from the behaviour middleware provides.
	parameterComponents, _ := components["parameters"].(map[string]any)
	if parameterComponents == nil {
		parameterComponents = map[string]any{}
	}
	if _, taken := parameterComponents[idempotencyComponentID]; taken {
		return nil, fmt.Errorf("openapi parameter %q is generated and must not be declared", idempotencyComponentID)
	}
	parameterComponents[idempotencyComponentID] = map[string]any{
		"name": idempotencyParameterName, "in": "header", "required": false,
		"schema": map[string]any{"type": "string", "maxLength": 255},
		"description": "Replays the stored response for a repeated key instead of acting twice. " +
			"A different body under the same key is a conflict.",
	}
	components["parameters"] = parameterComponents
	if schemaIDs["parameters"] == nil {
		schemaIDs["parameters"] = make(map[string]string)
	}
	schemaIDs["parameters"][idempotencyComponentID] = "generated"

	if len(tags) > 0 {
		sort.Slice(tags, func(i, j int) bool {
			return tags[i].(map[string]any)["name"].(string) < tags[j].(map[string]any)["name"].(string)
		})
		document["tags"] = tags
	}
	document["paths"] = paths
	document["components"] = components

	if err := checkOpenAPIRefs(document, schemaIDs); err != nil {
		return nil, err
	}
	return document, nil
}

// buildOperation renders one operation, deriving what the route already knows.
func buildOperation(moduleID string, op OpenAPIOperation, r RouteContribution) (map[string]any, error) {
	out := map[string]any{
		"operationId": op.OperationID,
		"summary":     op.Summary,
	}
	if op.Summary == "" {
		return nil, fmt.Errorf("openapi operation %s has no summary", op.OperationID)
	}
	if op.Description != "" {
		out["description"] = op.Description
	}
	if len(op.Tags) > 0 {
		out["tags"] = op.Tags
	}

	// Scope, not restated: a read token must not appear to satisfy a write, and
	// an unauthenticated route must say so rather than inheriting a default.
	switch r.Scope {
	case RouteAPIRead:
		out["security"] = []any{map[string]any{bearerSchemeName: []any{"read"}}}
	case RouteAPIWrite:
		out["security"] = []any{map[string]any{bearerSchemeName: []any{"write"}}}
	default:
		out["security"] = []any{}
	}

	parameters := make([]any, 0)
	if len(op.Parameters) > 0 {
		value, err := decodeJSON(op.Parameters)
		if err != nil {
			return nil, fmt.Errorf("module %s openapi %s parameters: %w", moduleID, op.OperationID, err)
		}
		list, ok := value.([]any)
		if !ok {
			return nil, fmt.Errorf("module %s openapi %s parameters must be an array", moduleID, op.OperationID)
		}
		parameters = append(parameters, list...)
	}
	// Derived from the route policy, so a route that accepts the key always
	// documents it and one that does not never claims to.
	if r.Policy.Idempotent {
		for _, existing := range parameters {
			if named, ok := existing.(map[string]any); ok && named["name"] == idempotencyParameterName {
				return nil, fmt.Errorf("openapi operation %s declares %s, which is generated from the route policy",
					op.OperationID, idempotencyParameterName)
			}
		}
		parameters = append(parameters, map[string]any{"$ref": idempotencyParameterRef})
	}
	if len(parameters) > 0 {
		out["parameters"] = parameters
	}

	if len(op.RequestBody) > 0 {
		value, err := decodeJSON(op.RequestBody)
		if err != nil {
			return nil, fmt.Errorf("module %s openapi %s requestBody: %w", moduleID, op.OperationID, err)
		}
		out["requestBody"] = value
	}
	if len(op.Responses) == 0 {
		return nil, fmt.Errorf("openapi operation %s declares no responses", op.OperationID)
	}
	responses, err := decodeJSON(op.Responses)
	if err != nil {
		return nil, fmt.Errorf("module %s openapi %s responses: %w", moduleID, op.OperationID, err)
	}
	out["responses"] = responses
	return out, nil
}

// decodeJSON turns a manifest fragment into plain Go values. yaml.Marshal sorts
// map keys, so the emitted document is byte-stable across runs.
func decodeJSON(raw json.RawMessage) (any, error) {
	var value any
	if err := json.Unmarshal(raw, &value); err != nil {
		return nil, err
	}
	return value, nil
}

// checkOpenAPIRefs walks the document for local $refs and refuses any that
// resolves to nothing. A dangling ref makes the document unusable to a client
// generator or validator, and is invisible until someone runs one.
func checkOpenAPIRefs(node any, defined map[string]map[string]string) error {
	switch value := node.(type) {
	case map[string]any:
		for _, key := range sortedKeys(value) {
			if key == "$ref" {
				ref, ok := value[key].(string)
				if !ok {
					return fmt.Errorf("openapi $ref is not a string: %v", value[key])
				}
				if err := checkLocalRef(ref, defined); err != nil {
					return err
				}
				continue
			}
			if err := checkOpenAPIRefs(value[key], defined); err != nil {
				return err
			}
		}
	case []any:
		for _, item := range value {
			if err := checkOpenAPIRefs(item, defined); err != nil {
				return err
			}
		}
	}
	return nil
}

func checkLocalRef(ref string, defined map[string]map[string]string) error {
	const prefix = "#/components/"
	if !strings.HasPrefix(ref, prefix) {
		// A remote ref would make the served contract depend on fetching
		// something else, which a client generator cannot rely on.
		return fmt.Errorf("openapi $ref %q is not a local components reference", ref)
	}
	parts := strings.Split(strings.TrimPrefix(ref, prefix), "/")
	if len(parts) != 2 {
		return fmt.Errorf("openapi $ref %q does not name a component", ref)
	}
	if _, ok := defined[parts[0]][parts[1]]; !ok {
		return fmt.Errorf("openapi $ref %q resolves to nothing", ref)
	}
	return nil
}

// emitQueriesRegistry renders query and table ownership. The generated sqlc
// package is one flat namespace shared by every module, so ownership is the only
// thing that makes a method name unambiguous and makes a cross-module read
// visible instead of accidental.
func emitQueriesRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	tableOwner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, d := range m.Data {
			if previous, clash := tableOwner[d.Table]; clash {
				return nil, fmt.Errorf("table %q is declared by both %s and %s", d.Table, previous, m.ID)
			}
			tableOwner[d.Table] = m.ID
		}
	}

	methodOwner := make(map[string]string)
	methodTable := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		dependencies := make(map[string]bool, len(m.Requires))
		for _, id := range m.Requires {
			dependencies[id] = true
		}
		for _, q := range m.Runtime.Queries {
			if previous, clash := methodOwner[q.Name]; clash {
				return nil, fmt.Errorf("sqlc method %q is declared by both %s and %s", q.Name, previous, m.ID)
			}
			owner, known := tableOwner[q.Table]
			if !known {
				return nil, fmt.Errorf("query %s reads table %q, which no module declares", q.Name, q.Table)
			}
			// Reading someone else's table is legal, but it has to be declared:
			// otherwise the query breaks silently when that module is removed.
			if owner != m.ID && !dependencies[owner] {
				return nil, fmt.Errorf("query %s (%s) reads table %q owned by %s without depending on it",
					q.Name, m.ID, q.Table, owner)
			}
			methodOwner[q.Name] = m.ID
			methodTable[q.Name] = q.Table
		}
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package db\n\n")
	b.WriteString("// QueryOwners maps each sqlc method to the module that owns it. The sqlc\n")
	b.WriteString("// package is one flat namespace, so this is what makes a method name\n")
	b.WriteString("// unambiguous and lets removal know which methods go with a module.\n")
	b.WriteString("var QueryOwners = map[string]string{\n")
	for _, name := range sortedKeys(methodOwner) {
		fmt.Fprintf(&b, "\t%s: %s,\n", goString(name), goString(methodOwner[name]))
	}
	b.WriteString("}\n\n")

	b.WriteString("// QueryTables maps each sqlc method to the table it reads or writes.\n")
	b.WriteString("var QueryTables = map[string]string{\n")
	for _, name := range sortedKeys(methodTable) {
		fmt.Fprintf(&b, "\t%s: %s,\n", goString(name), goString(methodTable[name]))
	}
	b.WriteString("}\n\n")

	b.WriteString("// TableOwners maps each table to the module that declares it. A module that\n")
	b.WriteString("// reads a table it does not own must depend on the owner.\n")
	b.WriteString("var TableOwners = map[string]string{\n")
	for _, table := range sortedKeys(tableOwner) {
		fmt.Fprintf(&b, "\t%s: %s,\n", goString(table), goString(tableOwner[table]))
	}
	b.WriteString("}\n")

	_ = ctx
	return &GeneratedFile{Path: "internal/db/queries_registry_gen.go", Content: b.String()}, nil
}

// generatedOwner marks a static file the build produces. The snapshot excludes
// generated outputs, so it is embedded but never installed or verified.
const generatedOwner = "(generated)"

// emitStaticRegistry renders the embed set and ownership for static assets.
// The embed patterns come from declarations, so a declared asset that is missing
// from the tree is a compile error and an undeclared asset is invisible to the
// binary — the Go compiler enforces coverage rather than a test.
func emitStaticRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	assets := make([]struct {
		path   string
		module string
	}, 0)
	owner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, f := range m.Files {
			if !strings.HasPrefix(f.Target, "static/") {
				continue
			}
			switch f.Class {
			case FileClassGenerated:
				// Built output, not distributed source: embedded so the binary
				// ships it, owned by the build step rather than a module.
				owner[f.Target] = generatedOwner
				assets = append(assets, struct {
					path   string
					module string
				}{strings.TrimPrefix(f.Target, "static/"), generatedOwner})
			case FileClassAsset:
				if previous, clash := owner[f.Target]; clash {
					return nil, fmt.Errorf("static asset %s is owned by both %s and %s", f.Target, previous, m.ID)
				}
				owner[f.Target] = m.ID
				assets = append(assets, struct {
					path   string
					module string
				}{strings.TrimPrefix(f.Target, "static/"), m.ID})
			case FileClassGo, FileClassTest:
				// Source, not an asset: embed patterns must not include Go files,
				// or the compiler refuses the pattern.
			default:
				return nil, fmt.Errorf("static file %s has class %q; a file under static/ is an asset, a generated output, or Go source",
					f.Target, f.Class)
			}
		}
	}
	sort.Slice(assets, func(i, j int) bool { return assets[i].path < assets[j].path })

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package static\n\n")
	b.WriteString("import \"embed\"\n\n")
	b.WriteString("// FS embeds every static asset a selected module declares. The patterns are\n")
	b.WriteString("// generated from those declarations, so the compiler itself refuses a declared\n")
	b.WriteString("// asset that is missing from the tree — coverage is the build, not a test.\n")
	b.WriteString("//\n//go:embed ")
	paths := make([]string, 0, len(assets))
	for _, a := range assets {
		paths = append(paths, a.path)
	}
	b.WriteString(strings.Join(paths, " "))
	b.WriteString("\nvar FS embed.FS\n\n")

	b.WriteString("// AssetOwners maps each static asset to the module that ships it, so removal\n")
	b.WriteString("// knows which files go with a module.\n")
	b.WriteString("var AssetOwners = map[string]string{\n")
	for _, a := range assets {
		fmt.Fprintf(&b, "\t%s: %s,\n", goString("static/"+a.path), goString(a.module))
	}
	b.WriteString("}\n\n")

	b.WriteString("// StaticRegistry lists module-owned static assets in load order.\n")
	b.WriteString("var StaticRegistry = []string{\n")
	for _, a := range assets {
		fmt.Fprintf(&b, "\t%s,\n", goString("static/"+a.path))
	}
	b.WriteString("}\n")

	_ = ctx
	return &GeneratedFile{Path: "static/embed_registry_gen.go", Content: b.String()}, nil
}

func emitUIComponentsRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	var b strings.Builder
	b.WriteString("// Code generated by ggg sync; DO NOT EDIT.\n")
	fmt.Fprintf(&b, "// index: %s\n", indexSHA(lock))
	b.WriteString("// The Alpine component names the installed modules expect to be registered.\n")
	b.WriteString("// Under CSP an unregistered x-data name is silently inert, so the shell\n")
	b.WriteString("// publishes what must exist and a dev check can compare it against Alpine.\n")
	b.WriteString("window.__gggComponents = window.__gggComponents || [];\n")
	seen := map[string]bool{}
	for _, m := range orderedModules(lock, graph) {
		for _, u := range m.Runtime.UI {
			if u.Alpine == "" || seen[u.Alpine] {
				continue
			}
			seen[u.Alpine] = true
			fmt.Fprintf(&b, "window.__gggComponents.push(%s);\n", goString(u.Alpine))
		}
	}
	_ = ctx
	return &GeneratedFile{Path: "static/ui-components.js", Content: b.String()}, nil
}

// emitAlpineFragments lists the Alpine source fragments the selected modules
// ship, in lock order. The shell renders one script tag per entry before
// alpine-csp boots, so installing or removing a module changes what the browser
// loads without editing the layout.
func emitAlpineFragments(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package ui\n\n")
	b.WriteString("// AlpineFragments are the module-owned Alpine sources, in load order.\n")
	b.WriteString("var AlpineFragments = []string{\n")
	for _, m := range orderedModules(lock, graph) {
		for _, a := range m.Runtime.Assets {
			// An engine asset is fetched on demand by the loader, so listing it
			// here would put the vendor file in the head of every page and make
			// the lazy design a no-op. Both kinds are "script"; the engine field
			// is what separates shell runtime from an on-demand runtime.
			if a.Kind == AssetScript && a.Engine == "" {
				fmt.Fprintf(&b, "\t%s,\n", goString("/"+a.Path))
			}
		}
	}
	b.WriteString("}\n")
	_ = ctx
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("format alpine fragment registry: %w", err)
	}
	return &GeneratedFile{Path: "internal/web/templates/ui/alpine_registry_gen.go", Content: string(src)}, nil
}

// emitEngineRegistry renders the lazily loaded engine assets. The shell's
// loader reads this to fetch a versioned vendor file the first time a matching
// data-ui-engine root appears, so an unused engine costs nothing.
func emitEngineRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	var b strings.Builder
	b.WriteString("// Code generated by ggg sync; DO NOT EDIT.\n")
	fmt.Fprintf(&b, "// index: %s\n", indexSHA(lock))
	b.WriteString("// Engine assets are fetched on demand by static/ui/engines.js, never with\n")
	b.WriteString("// the shell: an unused engine must cost nothing.\n")
	b.WriteString("window.__gggEngines = window.__gggEngines || {};\n")
	owner := map[string]string{}
	for _, m := range orderedModules(lock, graph) {
		for _, a := range m.Runtime.Assets {
			if a.Engine == "" {
				continue
			}
			if prior, ok := owner[a.Engine]; ok {
				return nil, fmt.Errorf("engine %q declared by both %s and %s", a.Engine, prior, m.ID)
			}
			owner[a.Engine] = m.ID
			fmt.Fprintf(&b, "window.__gggEngines[%s] = { src: %s, integrity: %s, esm: %t };\n",
				jsString(a.Engine), jsString("/"+a.Path), jsString(a.Integrity), a.ESM)
		}
	}
	_ = ctx
	return &GeneratedFile{Path: "static/ui-engines.js", Content: b.String()}, nil
}

// jsString renders a Go string as a JSON string literal, which is also a valid
// JavaScript one. Hand-rolled quoting here would be an escaping bug waiting to
// reach a script tag.
func jsString(value string) string {
	encoded, err := json.Marshal(value)
	if err != nil {
		return `""`
	}
	return string(encoded)
}

// tailwindEntry is the stylesheet the build is invoked on. It imports the
// generated per-module registry, so it can never be one of its entries.
const tailwindEntry = "input.css"

func emitStylesRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	var b strings.Builder
	b.WriteString("/* Code generated by ggg sync; DO NOT EDIT. */\n")
	fmt.Fprintf(&b, "/* index: %s */\n", indexSHA(lock))
	for _, m := range orderedModules(lock, graph) {
		for _, f := range m.Files {
			// The Tailwind entry is a style file, but it is the file that
			// imports this registry - listing it here would import the entry
			// into itself.
			if f.Class == FileClassStyle && f.Target != tailwindEntry {
				fmt.Fprintf(&b, "@import \"%s\";\n", f.Target)
			}
		}
	}
	_ = ctx
	return &GeneratedFile{Path: "internal/web/styles/modules_registry_gen.css", Content: b.String()}, nil
}

// emitUIComponentRegistry renders installed UI component metadata. The gallery
// reference reads this instead of a hand-kept list, so a component's family,
// owning module and progressive-enhancement engine always describe what is
// actually installed — and uninstalling a module removes its entries.
func emitUIComponentRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package ui\n\n")
	b.WriteString("// Component describes one installed UI component.\n")
	b.WriteString("type Component struct {\n")
	b.WriteString("\tName   string\n\tFamily GalleryFamily\n\tModule string\n")
	b.WriteString("\tEngine string\n\tAlpine string\n\tVendor string\n")
	b.WriteString("\tNativeFallback string\n")
	b.WriteString("}\n\n")
	b.WriteString("// ComponentRegistry lists every installed component in module order.\n")
	b.WriteString("var ComponentRegistry = []Component{\n")
	owner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, c := range m.Runtime.UI {
			if prior, ok := owner[c.Name]; ok {
				return nil, fmt.Errorf("ui component %q declared by both %s and %s", c.Name, prior, m.ID)
			}
			owner[c.Name] = m.ID
			fmt.Fprintf(&b, "\t{Name: %s, Family: %s, Module: %s",
				goString(c.Name), goString(string(c.Family)), goString(m.ID))
			if c.Engine != "" {
				fmt.Fprintf(&b, ", Engine: %s", goString(c.Engine))
			}
			if c.Alpine != "" {
				fmt.Fprintf(&b, ", Alpine: %s", goString(c.Alpine))
			}
			if c.Vendor != "" {
				fmt.Fprintf(&b, ", Vendor: %s", goString(c.Vendor))
			}
			if c.NativeFallback != "" {
				fmt.Fprintf(&b, ", NativeFallback: %s", goString(c.NativeFallback))
			}
			b.WriteString("},\n")
		}
	}
	b.WriteString("}\n")
	_ = ctx
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("format ui component registry: %w", err)
	}
	return &GeneratedFile{Path: "internal/web/templates/ui/components_registry_gen.go", Content: string(src)}, nil
}

// emitUIReferenceRegistry renders the prose half of a component's public
// interface: its exact renderer signature, what it is for, what it refuses to
// do, its keyboard contract and the states it actually has. The gallery detail
// pages read this instead of carrying hand-written copy, so documentation for a
// component cannot outlive the module that ships it. It is a separate file from
// the component metadata because the two have different readers — coverage
// tests want the terse installed set, the reference wants the narrative — and
// splitting them keeps a copy edit out of the file gallery coverage compares.
func emitUIReferenceRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package ui\n\n")
	b.WriteString("// Reference is the documented interface of one installed UI component.\n")
	b.WriteString("// Signature, Summary, Guidance and Keyboard are declared by the owning\n")
	b.WriteString("// module; an absent Keyboard means the component adds no key handling of its\n")
	b.WriteString("// own, which is a different statement from unknown.\n")
	b.WriteString("type Reference struct {\n")
	b.WriteString("\tName      string\n\tFamily    GalleryFamily\n\tModule    string\n")
	b.WriteString("\tSignature string\n\tSummary   string\n\tGuidance  string\n")
	b.WriteString("\tKeyboard  string\n\tStates    []string\n")
	b.WriteString("}\n\n")
	b.WriteString("// ReferenceRegistry documents every installed component in module order,\n")
	b.WriteString("// matching ComponentRegistry entry for entry.\n")
	b.WriteString("var ReferenceRegistry = []Reference{\n")
	owner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, c := range m.Runtime.UI {
			if prior, ok := owner[c.Name]; ok {
				return nil, fmt.Errorf("ui component %q declared by both %s and %s", c.Name, prior, m.ID)
			}
			owner[c.Name] = m.ID
			fmt.Fprintf(&b, "\t{Name: %s, Family: %s, Module: %s",
				goString(c.Name), goString(string(c.Family)), goString(m.ID))
			if c.Signature != "" {
				fmt.Fprintf(&b, ", Signature: %s", goString(c.Signature))
			}
			if c.Summary != "" {
				fmt.Fprintf(&b, ", Summary: %s", goString(c.Summary))
			}
			if c.Guidance != "" {
				fmt.Fprintf(&b, ", Guidance: %s", goString(c.Guidance))
			}
			if c.Keyboard != "" {
				fmt.Fprintf(&b, ", Keyboard: %s", goString(c.Keyboard))
			}
			if len(c.States) > 0 {
				fmt.Fprintf(&b, ", States: %s", goStringSlice(c.States))
			}
			b.WriteString("},\n")
		}
	}
	b.WriteString("}\n\n")
	// Built once rather than scanned per call: every gallery detail request
	// resolves a component name, and the registry grows with the catalog.
	b.WriteString("var referenceIndex = func() map[string]int {\n")
	b.WriteString("\tindex := make(map[string]int, len(ReferenceRegistry))\n")
	b.WriteString("\tfor i := range ReferenceRegistry {\n")
	b.WriteString("\t\tindex[ReferenceRegistry[i].Name] = i\n")
	b.WriteString("\t}\n\treturn index\n}()\n\n")
	b.WriteString("// ReferenceFor returns the documented interface of an installed component.\n")
	b.WriteString("// A missing name is not an error: it is how a caller learns the module that\n")
	b.WriteString("// owns that component is not installed.\n")
	b.WriteString("func ReferenceFor(name string) (Reference, bool) {\n")
	b.WriteString("\tat, ok := referenceIndex[name]\n")
	b.WriteString("\tif !ok {\n\t\treturn Reference{}, false\n\t}\n")
	b.WriteString("\treturn ReferenceRegistry[at], true\n}\n")
	_ = ctx
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("format ui reference registry: %w", err)
	}
	return &GeneratedFile{Path: "internal/web/templates/ui/reference_gen.go", Content: string(src)}, nil
}

// declaredScenarios merges scenario declarations in module order with
// exclusive-slug enforcement. Two modules claiming one slug is refused rather
// than resolved: the slug is a URL and a baseline file name, so silently
// letting one win would move a screenshot without anything saying so.
func declaredScenarios(lock Lock, graph []Manifest) ([]ScenarioContribution, error) {
	out := make([]ScenarioContribution, 0)
	owner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, s := range m.Runtime.Scenarios {
			if prior, clash := owner[s.Slug]; clash {
				return nil, fmt.Errorf("scenario %q is declared by both %s and %s", s.Slug, prior, m.ID)
			}
			owner[s.Slug] = m.ID
			out = append(out, s)
		}
	}
	return out, nil
}

// emitScenarioRegistry renders the dev-catalog scenario descriptors. The Go
// table and the visual surface matrix are both rendered from this one
// declaration, so the catalog cannot claim a surface the comparison job never
// captures.
func emitScenarioRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	declared, err := declaredScenarios(lock, graph)
	if err != nil {
		return nil, err
	}
	if len(declared) == 0 {
		return nil, nil
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package templates\n\n")
	b.WriteString("// scenarioDescriptor is one declared dev scenario without its composition.\n")
	b.WriteString("// The renderer is hand-owned Go, so it is joined onto this table rather than\n")
	b.WriteString("// named here: a manifest cannot reference a function.\n")
	b.WriteString("type scenarioDescriptor struct {\n")
	b.WriteString("\tSlug     string\n\tTitle    string\n\tSummary  string\n")
	b.WriteString("\tLayout   string\n\tSurfaces []string\n\tStates   []string\n")
	b.WriteString("}\n\n")
	b.WriteString("// scenarioDescriptors is every declared scenario in module order.\n")
	b.WriteString("var scenarioDescriptors = []scenarioDescriptor{\n")
	for _, s := range declared {
		fmt.Fprintf(&b, "\t{Slug: %s, Title: %s, Layout: %s,\n",
			goString(s.Slug), goString(s.Title), goString(s.Layout))
		fmt.Fprintf(&b, "\t\tSummary: %s,\n", goString(s.Summary))
		fmt.Fprintf(&b, "\t\tSurfaces: %s,\n", goStringSlice(s.Surfaces))
		fmt.Fprintf(&b, "\t\tStates: %s},\n", goStringSlice(s.States))
	}
	b.WriteString("}\n")
	_ = ctx
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("format scenario registry: %w", err)
	}
	return &GeneratedFile{Path: "internal/web/templates/scenarios_gen.go", Content: string(src)}, nil
}

// tsStringArray renders a TypeScript array literal with single-quoted members,
// matching the style of the hand-written specs that read it.
func tsStringArray(values []string) string {
	if len(values) == 0 {
		return "[]"
	}
	parts := make([]string, 0, len(values))
	for _, v := range values {
		parts = append(parts, tsString(v))
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// tsString single-quotes a TypeScript string. A selector may legitimately
// contain a quote of its own, so the escape is not optional.
func tsString(value string) string {
	escaped := strings.ReplaceAll(value, "\\", "\\\\")
	escaped = strings.ReplaceAll(escaped, "'", "\\'")
	return "'" + escaped + "'"
}

// emitVisualSurfaces renders the surface matrix the visual and accessibility
// runners iterate. Family sheets, scenario compositions and product pages are
// one list because the runners treat them identically: visit a path as a
// persona and compare. Their differing capture rules are data on each entry
// rather than three code paths in the spec.
func emitVisualSurfaces(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	scenarios, err := declaredScenarios(lock, graph)
	if err != nil {
		return nil, err
	}
	pages, err := declaredVisual(lock, graph)
	if err != nil {
		return nil, err
	}
	if len(scenarios) == 0 && len(pages) == 0 {
		return nil, nil
	}

	var b strings.Builder
	b.WriteString("// Generated by ggg sync; DO NOT EDIT.\n")
	b.WriteString("export type SurfaceKind = 'family' | 'scenario' | 'page';\n")
	b.WriteString("export type Viewport = 'desktop' | 'mobile';\n\n")
	b.WriteString("export interface Surface {\n")
	b.WriteString("  id: string;\n")
	b.WriteString("  kind: SurfaceKind;\n")
	b.WriteString("  path: string;\n")
	b.WriteString("  fullPage: boolean;\n")
	b.WriteString("  viewports: Viewport[];\n")
	b.WriteString("  persona: string;\n")
	b.WriteString("  masks: string[];\n")
	b.WriteString("}\n\n")
	b.WriteString("export const surfaces: Surface[] = [\n")

	// A family sheet's whole value is that nothing in the component layer
	// escapes the frame, so it is compared full-page at one width and signed in
	// as nobody: the reference renders the same for every reader.
	for _, family := range GalleryFamilies {
		writeSurface(&b, "family-"+string(family), "family",
			"/dev/gallery/"+string(family), true, []string{"desktop"}, "", nil)
	}
	// A scenario is a product surface, so it is compared at the fold in both
	// widths. Its compositions are proven byte-identical, which is why it
	// declares no masks: a mask here would hide a real regression.
	for _, s := range scenarios {
		persona := ""
		if s.Layout == "app" || s.Layout == "admin" {
			persona = "admin"
		}
		writeSurface(&b, "scenario-"+s.Slug, "scenario",
			"/dev/scenarios/"+s.Slug, false, []string{"desktop", "mobile"}, persona, nil)
	}
	for _, p := range pages {
		writeSurface(&b, p.ID, "page", p.Path, p.FullPage, p.Viewports, p.Persona, p.Masks)
	}
	b.WriteString("];\n")
	_ = ctx
	_ = modulePath
	return &GeneratedFile{Path: "e2e/generated/surfaces.ts", Content: b.String()}, nil
}

func writeSurface(b *strings.Builder, id, kind, path string, fullPage bool, viewports []string, persona string, masks []string) {
	fmt.Fprintf(b, "  { id: %s, kind: '%s', path: %s, fullPage: %t, viewports: %s, persona: %s, masks: %s },\n",
		tsString(id), kind, tsString(path), fullPage,
		tsStringArray(viewports), tsString(persona), tsStringArray(masks))
}

// declaredVisual merges page-surface declarations in module order. Ids are
// exclusive because each one is a committed screenshot file name; two modules
// claiming one would compare two different pages against one baseline. A
// persona must be one the fixtures seed, or the capture would authenticate as
// nobody and silently record a redirect.
func declaredVisual(lock Lock, graph []Manifest) ([]VisualContribution, error) {
	personas, err := declaredPersonas(lock, graph)
	if err != nil {
		return nil, err
	}
	known := make(map[string]struct{}, len(personas))
	for _, p := range personas {
		known[p.ID] = struct{}{}
	}
	out := make([]VisualContribution, 0)
	owner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, v := range m.Runtime.Visual {
			if prior, clash := owner[v.ID]; clash {
				return nil, fmt.Errorf("visual surface %q is declared by both %s and %s", v.ID, prior, m.ID)
			}
			owner[v.ID] = m.ID
			if v.Persona != "" {
				if _, ok := known[v.Persona]; !ok {
					return nil, fmt.Errorf("visual surface %q names undeclared persona %q", v.ID, v.Persona)
				}
			}
			out = append(out, v)
		}
	}
	return out, nil
}

func emitContentRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package content\n\n")
	b.WriteString("// ContentRegistry lists selected content types.\n")
	b.WriteString("var ContentRegistry = []string{\n")
	for _, m := range orderedModules(lock, graph) {
		for _, c := range m.Runtime.ContentTypes {
			fmt.Fprintf(&b, "\t%s,\n", goString(c.ID))
		}
	}
	b.WriteString("}\n")
	_ = ctx
	return &GeneratedFile{Path: "content/embed_registry_gen.go", Content: b.String()}, nil
}

func emitConfigRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	declarations, err := declaredEnvironment(lock, graph)
	if err != nil {
		return nil, err
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package config\n\n")

	needsTime := false
	for _, e := range declarations {
		if e.Type == EnvTime {
			needsTime = true
		}
	}
	b.WriteString("import (\n\t\"errors\"\n\t\"fmt\"\n\t\"strconv\"\n\t\"strings\"\n")
	if needsTime {
		b.WriteString("\t\"time\"\n")
	}
	b.WriteString(")\n\n")

	b.WriteString("// ConfigRegistry lists module-owned environment declarations in manifest order.\n")
	b.WriteString("var ConfigRegistry = []string{\n")
	for _, e := range declarations {
		fmt.Fprintf(&b, "\t%s,\n", goString(e.Key))
	}
	b.WriteString("}\n\n")

	// The struct is generated so a key and its Go field have exactly one owner:
	// a module cannot add a setting without also declaring where it lands.
	b.WriteString("// Config is the parsed environment. Every field is declared by the module\n")
	b.WriteString("// that consumes it; behaviour over these values lives in config.go.\n")
	b.WriteString("type Config struct {\n")
	for _, e := range declarations {
		fmt.Fprintf(&b, "\t// %s: %s\n", e.Key, e.Description)
		fmt.Fprintf(&b, "\t%s %s\n", e.Field, goEnvType(e.Type))
	}
	b.WriteString("}\n\n")

	b.WriteString("// parseDeclared reads every declared key and reports every problem it finds,\n")
	b.WriteString("// in declaration order. It never returns early: an operator fixing one bad\n")
	b.WriteString("// value should not have to re-run to discover the next.\n")
	b.WriteString("func parseDeclared(lookup func(string) string) (Config, []error) {\n")
	b.WriteString("\tvar cfg Config\n\tvar errs []error\n")
	for _, e := range declarations {
		if err := writeEnvParse(&b, e); err != nil {
			return nil, err
		}
	}
	b.WriteString("\treturn cfg, errs\n}\n\n")

	// Production requirements are data: the module that needs a key in
	// production is the module that declares it.
	b.WriteString("// requireProductionKeys reports every declared key that production cannot\n")
	b.WriteString("// boot without. Absent here means the dev fallback is genuinely safe.\n")
	b.WriteString("func requireProductionKeys(lookup func(string) string) []error {\n")
	b.WriteString("\tvar errs []error\n")
	for _, e := range declarations {
		if e.ProductionRequired {
			fmt.Fprintf(&b, "\tif lookup(%s) == \"\" {\n", goString(e.Key))
			fmt.Fprintf(&b, "\t\terrs = append(errs, errors.New(%s))\n",
				goString(e.Key+" is required when APP_ENV=production"))
			b.WriteString("\t}\n")
		}
	}
	b.WriteString("\treturn errs\n}\n")

	_ = ctx
	return &GeneratedFile{Path: "internal/config/config_registry_gen.go", Content: b.String()}, nil
}

// declaredEnvironment is every selected module's env declarations in manifest
// order, keys sorted within a module, with one owner per key.
func declaredEnvironment(lock Lock, graph []Manifest) ([]EnvironmentVariable, error) {
	out := make([]EnvironmentVariable, 0)
	keyOwner := make(map[string]string)
	fieldOwner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		envs := append([]EnvironmentVariable{}, m.Environment...)
		sort.Slice(envs, func(i, j int) bool { return envs[i].Key < envs[j].Key })
		for _, e := range envs {
			if previous, clash := keyOwner[e.Key]; clash {
				return nil, fmt.Errorf("env key %q is declared by both %s and %s", e.Key, previous, m.ID)
			}
			if previous, clash := fieldOwner[e.Field]; clash {
				return nil, fmt.Errorf("config field %q is declared by both %s and %s", e.Field, previous, m.ID)
			}
			if !e.Type.Valid() {
				return nil, fmt.Errorf("env key %s: type %q is not one of string, int, bool, time", e.Key, e.Type)
			}
			if !validIdentifier(e.Field) {
				return nil, fmt.Errorf("env key %s: field %q is not a Go identifier", e.Key, e.Field)
			}
			keyOwner[e.Key], fieldOwner[e.Field] = m.ID, m.ID
			out = append(out, e)
		}
	}
	return out, nil
}

func goEnvType(t EnvType) string {
	switch t {
	case EnvInt:
		return "int"
	case EnvBool:
		return "bool"
	case EnvTime:
		return "time.Time"
	default:
		return "string"
	}
}

// writeEnvParse emits the parse for one declaration. Each parse appends to errs
// and leaves the field at its default on failure, so a later key is still read.
func writeEnvParse(b *strings.Builder, e EnvironmentVariable) error {
	key := goString(e.Key)
	switch e.Type {
	case EnvString:
		read := fmt.Sprintf("pick(lookup, %s, %s)", key, goString(e.Default))
		if e.TrimSlash {
			read = fmt.Sprintf("strings.TrimRight(%s, \"/\")", read)
		}
		fmt.Fprintf(b, "\tcfg.%s = %s\n", e.Field, read)
		if len(e.Enum) > 0 {
			fmt.Fprintf(b, "\tswitch cfg.%s {\n\tcase ", e.Field)
			for i, v := range e.Enum {
				if i > 0 {
					b.WriteString(", ")
				}
				b.WriteString(goString(v))
			}
			b.WriteString(":\n\tdefault:\n")
			fmt.Fprintf(b, "\t\terrs = append(errs, fmt.Errorf(\"%s: %%q must be one of %s\", cfg.%s))\n",
				e.Key, strings.Join(e.Enum, ", "), e.Field)
			b.WriteString("\t}\n")
		}
		if e.Required {
			fmt.Fprintf(b, "\tif cfg.%s == \"\" {\n", e.Field)
			fmt.Fprintf(b, "\t\terrs = append(errs, errors.New(%s))\n\t}\n", goString(e.Key+" is required"))
		}
	case EnvBool:
		fmt.Fprintf(b, "\tcfg.%s = parseBool(pick(lookup, %s, %s))\n", e.Field, key, goString(e.Default))
	case EnvInt:
		if e.Default != "" {
			if _, err := strconv.Atoi(e.Default); err != nil {
				return fmt.Errorf("env key %s: default %q is not an integer", e.Key, e.Default)
			}
			fmt.Fprintf(b, "\tcfg.%s = %s\n", e.Field, e.Default)
		}
		fmt.Fprintf(b, "\tif raw := pick(lookup, %s, \"\"); raw != \"\" {\n", key)
		b.WriteString("\t\tvalue, err := strconv.Atoi(raw)\n")
		condition, explanation := intBound(e)
		fmt.Fprintf(b, "\t\tif err != nil%s {\n", condition)
		fmt.Fprintf(b, "\t\t\terrs = append(errs, fmt.Errorf(\"%s: %%q %s\", raw))\n", e.Key, explanation)
		b.WriteString("\t\t} else {\n")
		fmt.Fprintf(b, "\t\t\tcfg.%s = value\n", e.Field)
		b.WriteString("\t\t}\n\t}\n")
	case EnvTime:
		fmt.Fprintf(b, "\tif raw := pick(lookup, %s, \"\"); raw != \"\" {\n", key)
		b.WriteString("\t\tvalue, err := time.Parse(time.RFC3339, raw)\n\t\tif err != nil {\n")
		fmt.Fprintf(b, "\t\t\terrs = append(errs, fmt.Errorf(\"%s: %%v\", err))\n\t\t} else {\n", e.Key)
		fmt.Fprintf(b, "\t\t\tcfg.%s = value\n", e.Field)
		b.WriteString("\t\t}\n\t}\n")
	}
	return nil
}

// intBound turns declared bounds into a condition and the message an operator
// reads. A one-sided bound says only what it means.
func intBound(e EnvironmentVariable) (condition, explanation string) {
	switch {
	case e.Min != nil && e.Max != nil:
		return fmt.Sprintf(" || value < %d || value > %d", *e.Min, *e.Max),
			fmt.Sprintf("must be an integer between %d and %d", *e.Min, *e.Max)
	case e.Min != nil:
		return fmt.Sprintf(" || value < %d", *e.Min),
			fmt.Sprintf("must be an integer >= %d", *e.Min)
	case e.Max != nil:
		return fmt.Sprintf(" || value > %d", *e.Max),
			fmt.Sprintf("must be an integer <= %d", *e.Max)
	default:
		return "", "must be an integer"
	}
}

// emitEnvExample renders the starting environment for a fresh clone. Non-secret
// defaults are filled in so `make dev` works with no accounts; secrets ship
// empty, because a plausible-looking fake value is the kind of thing that
// reaches production.
// emitDataLifecycleRegistry renders the stateful-data obligations every
// selected module declares: what a table's delete behaviour is supposed to be
// and whether its rows are exportable. Deletion paths and export collectors
// are hand-written where the work is genuine (redaction DTOs, sole-admin
// guards); what is generated is the obligation those paths are checked against,
// so a module that declares data cannot be installed into silence.
func emitDataLifecycleRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	declared := make([]DataDeclaration, 0)
	tableOwner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, d := range m.Data {
			if previous, clash := tableOwner[d.Table]; clash {
				return nil, fmt.Errorf("table %q is declared by both %s and %s", d.Table, previous, m.ID)
			}
			tableOwner[d.Table] = m.ID
			declared = append(declared, d)
		}
	}
	if len(declared) == 0 {
		return nil, nil
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package db\n\n")
	b.WriteString("// DataLifecycle is one declared data obligation: the delete behaviour the\n")
	b.WriteString("// schema is expected to provide and whether the rows are exportable.\n")
	b.WriteString("type DataLifecycle struct {\n")
	b.WriteString("\tTable string\n\tModule string\n\tScope string\n\tExport bool\n")
	b.WriteString("\tAccountDelete string\n\tOrganizationDelete string\n}\n\n")
	b.WriteString("// DataLifecycleRegistry lists every declared table in module order. Export\n")
	b.WriteString("// collectors and deletion paths are checked against this list, so a module\n")
	b.WriteString("// that declares data cannot be omitted from either silently.\n")
	b.WriteString("var DataLifecycleRegistry = []DataLifecycle{\n")
	for _, d := range declared {
		fmt.Fprintf(&b, "\t{Table: %s, Module: %s, Scope: %q, Export: %v, AccountDelete: %q, OrganizationDelete: %q},\n",
			goString(d.Table), goString(tableOwner[d.Table]), d.Scope, d.Export, d.AccountDelete, d.OrganizationDelete)
	}
	b.WriteString("}\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/db/data_lifecycle_registry_gen.go", Content: b.String()}, nil
}

// emitSeedRegistry renders seed-fragment order per fixture set. A module's
// fixture is a file it owns, so installing the module installs its demo rows
// and removing it takes them out of the load order — the aggregate order is
// the lock's module order, which is dependency-sorted, so a fragment never
// loads before the rows it references.
func emitSeedRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	sets := map[string][]string{"dev": {}, "e2e": {}}
	for _, m := range orderedModules(lock, graph) {
		for _, f := range m.Files {
			if f.Class != FileClassSeed {
				continue
			}
			set := seedSetFor(f.Target)
			if set == "" {
				return nil, fmt.Errorf("seed fragment %s must live under internal/db/testdata/seed/{dev,e2e}/", f.Target)
			}
			sets[set] = append(sets[set], f.Target)
		}
	}
	if len(sets["dev"])+len(sets["e2e"]) == 0 {
		return nil, nil
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package db\n\n")
	b.WriteString("// SeedFragments lists seed fragments per fixture set, in module order. The\n")
	b.WriteString("// loader executes them in this order; fragments are idempotent so the set is\n")
	b.WriteString("// re-runnable. Order is the lock's dependency order, so a fragment never\n")
	b.WriteString("// loads before the rows it references.\n")
	personas, err := declaredPersonas(lock, graph)
	if err != nil {
		return nil, err
	}
	b.WriteString("// PersonaRecords mirrors the generated e2e personas in Go, so the\n")
	b.WriteString("// fixture-parity check reads the same declaration the specs do.\n")
	b.WriteString("var PersonaRecords = []struct{ ID, User, Org, Role string }{\n")
	for _, p := range personas {
		fmt.Fprintf(&b, "\t{ID: %s, User: %s, Org: %s, Role: %s},\n",
			goString(p.ID), goString(p.User), goString(p.Org), goString(p.Role))
	}
	b.WriteString("}\n\n")

	b.WriteString("var SeedFragments = map[string][]string{\n")
	for _, set := range []string{"dev", "e2e"} {
		if len(sets[set]) == 0 {
			continue
		}
		fmt.Fprintf(&b, "\t%s: {\n", goString(set))
		for _, frag := range sets[set] {
			fmt.Fprintf(&b, "\t\t%s,\n", goString(frag))
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/db/seed_registry_gen.go", Content: b.String()}, nil
}

// seedSetFor maps a fragment path to its fixture set.
func seedSetFor(target string) string {
	for _, set := range []string{"dev", "e2e"} {
		if strings.HasPrefix(target, "internal/db/testdata/seed/"+set+"/") {
			return set
		}
	}
	return ""
}

// declaredPersonas merges persona declarations with exclusive-id enforcement.
func declaredPersonas(lock Lock, graph []Manifest) ([]PersonaContribution, error) {
	out := make([]PersonaContribution, 0)
	owner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, p := range m.Personas {
			if previous, clash := owner[p.ID]; clash {
				return nil, fmt.Errorf("persona %q is declared by both %s and %s", p.ID, previous, m.ID)
			}
			owner[p.ID] = m.ID
			if p.User == "" {
				return nil, fmt.Errorf("persona %q declares no user id", p.ID)
			}
			if (p.Org == "") != (p.Role == "") {
				return nil, fmt.Errorf("persona %q must declare both org and role or neither", p.ID)
			}
			out = append(out, p)
		}
	}
	return out, nil
}

// emitPersonasRegistry renders the shared actor list for e2e. The cookie
// helper is derived from it, so a spec and a fixture cannot disagree about who
// an actor is: the session format is built once, here, from the declaration.
func emitPersonasRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	declared, err := declaredPersonas(lock, graph)
	if err != nil {
		return nil, err
	}
	if len(declared) == 0 {
		return nil, nil
	}

	ids := make([]string, 0, len(declared))
	for _, p := range declared {
		ids = append(ids, "'"+p.ID+"'")
	}

	var b strings.Builder
	b.WriteString("// Generated by ggg sync; DO NOT EDIT. Personas are declared by modules —\n")
	b.WriteString("// identity owns the actors and a workflow may add one for the surface it\n")
	b.WriteString("// tests — and this file is the single source both the specs and the seeded\n")
	b.WriteString("// fixtures agree with.\n\n")
	fmt.Fprintf(&b, "export type PersonaId = %s;\n\n", strings.Join(ids, " | "))
	b.WriteString("export interface Persona {\n  id: PersonaId;\n  user: string;\n  org: string;\n  role: string;\n}\n\n")
	b.WriteString("export const personas: Persona[] = [\n")
	for _, p := range declared {
		fmt.Fprintf(&b, "  { id: '%s', user: '%s', org: '%s', role: '%s' },\n",
			p.ID, p.User, p.Org, p.Role)
	}
	b.WriteString("];\n\n")
	b.WriteString("// sessionFor builds the DEV_AUTH_BYPASS cookie value for a persona. An\n")
	b.WriteString("// org-less actor carries empty org and role, which the session parser reads\n")
	b.WriteString("// as no active organization.\n")
	b.WriteString("export function sessionFor(p: PersonaId): string {\n")
	b.WriteString("  const persona = personas.find((x) => x.id === p);\n")
	b.WriteString("  if (!persona) throw new Error(`unknown persona ${p}`);\n")
	b.WriteString("  return `e2e:${persona.user}:${persona.org}:${persona.role}`;\n")
	b.WriteString("}\n")
	_ = ctx
	_ = modulePath
	return &GeneratedFile{Path: "e2e/generated/personas.ts", Content: b.String()}, nil
}

func emitEnvExample(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	declarations, err := declaredEnvironment(lock, graph)
	if err != nil {
		return nil, err
	}

	var b strings.Builder
	b.WriteString("# Generated by ggg sync; DO NOT EDIT.\n")
	b.WriteString("#\n")
	b.WriteString("# Every key a selected module declares. Copy to .env and edit; .env is\n")
	b.WriteString("# auto-loaded in development only and never overrides the real environment.\n")
	b.WriteString("# Secrets are intentionally blank. Keys marked production-required have no\n")
	b.WriteString("# fallback when APP_ENV=production.\n")

	byModule := make(map[string][]EnvironmentVariable)
	order := make([]string, 0)
	owner := envOwners(lock, graph)
	for _, e := range declarations {
		id := owner[e.Key]
		if _, seen := byModule[id]; !seen {
			order = append(order, id)
		}
		byModule[id] = append(byModule[id], e)
	}

	for _, id := range order {
		fmt.Fprintf(&b, "\n# --- %s ---\n", id)
		for _, e := range byModule[id] {
			fmt.Fprintf(&b, "\n# %s\n", e.Description)
			if e.ProductionRequired {
				b.WriteString("# Required when APP_ENV=production.\n")
			}
			if len(e.Enum) > 0 {
				fmt.Fprintf(&b, "# One of: %s\n", strings.Join(e.Enum, ", "))
			}
			if bounds := boundsText(e); bounds != "" {
				fmt.Fprintf(&b, "# %s\n", bounds)
			}
			// Example wins where a module states one; otherwise a secret ships
			// blank and everything else ships its default.
			value := e.Default
			if e.Secret {
				value = ""
			}
			if e.Example != "" {
				value = e.Example
			}
			fmt.Fprintf(&b, "%s=%s\n", e.Key, value)
		}
	}

	_ = modulePath
	_ = ctx
	return &GeneratedFile{Path: ".env.example", Content: b.String()}, nil
}

// emitConfigReference renders the exhaustive key table. It is generated from the
// same records as the parse, so the documented surface and the parsed surface
// cannot drift — the omissions this repo shipped with were exactly that.
func emitConfigReference(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	declarations, err := declaredEnvironment(lock, graph)
	if err != nil {
		return nil, err
	}
	owner := envOwners(lock, graph)

	var b strings.Builder
	b.WriteString("---\n")
	b.WriteString("title: Configuration reference\n")
	b.WriteString("description: Every environment variable a selected module declares, generated from the module manifests.\n")
	b.WriteString("section: Core\n")
	b.WriteString("weight: 5\n")
	b.WriteString("---\n\n")
	b.WriteString("<!-- Generated by ggg sync; DO NOT EDIT. Edit the declaring module's manifest. -->\n\n")
	b.WriteString("Generated from the `environment` declarations of every selected module, which\n")
	b.WriteString("are the same records `config.Load()` parses. A key cannot be read without\n")
	b.WriteString("appearing here, and every listed key ships in `.env.example`.\n\n")
	b.WriteString("See [Configuration](/docs/configuration) for how loading, validation, and\n")
	b.WriteString("degradation behave.\n\n")
	b.WriteString("| Key | Module | Required | Default | Notes |\n")
	b.WriteString("|---|---|---|---|---|\n")
	for _, e := range declarations {
		required := ""
		switch {
		case e.Required:
			required = "**always**"
		case e.ProductionRequired:
			required = "**production**"
		}
		def := ""
		if e.Default != "" {
			def = "`" + e.Default + "`"
		}
		notes := escapeTableCell(e.Description)
		if bounds := boundsText(e); bounds != "" {
			notes += ". " + bounds
		}
		if e.Secret {
			notes += ". Secret: ships blank in `.env.example`"
		}
		fmt.Fprintf(&b, "| `%s` | `%s` | %s | %s | %s |\n",
			e.Key, owner[e.Key], required, escapeTableCell(def), notes)
	}

	_ = modulePath
	_ = ctx
	return &GeneratedFile{Path: "content/docs/configuration-reference.md", Content: b.String()}, nil
}

// moduleKindOrder is the order the module reference walks kinds in. It runs
// from the smallest unit of composition to the largest, because that is the
// order a reader builds understanding in: an element is a leaf, a system is a
// provider with a lifecycle. Declared rather than sorted alphabetically, which
// would open with "component" and bury "element" in the middle.
var moduleKindOrder = []ModuleKind{
	ModuleElement, ModuleComponent, ModulePage, ModuleWorkflow, ModuleSystem,
}

// emitModuleReference renders the installed catalog as a table per kind. A
// hand-kept inventory of this size is a list that is wrong within a week, and
// the facts a reader wants — what a module needs and what removing it costs —
// are exactly the fields the planner and the remover branch on.
func emitModuleReference(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	byKind := make(map[ModuleKind][]Manifest, len(moduleKindOrder))
	for _, m := range orderedModules(lock, graph) {
		if m.TestOnly {
			continue
		}
		byKind[m.Kind] = append(byKind[m.Kind], m)
	}
	for kind := range byKind {
		modules := byKind[kind]
		sort.Slice(modules, func(i, j int) bool { return modules[i].ID < modules[j].ID })
	}

	var b strings.Builder
	b.WriteString("---\n")
	b.WriteString("title: Module reference\n")
	b.WriteString("description: Every installed module, its dependencies, and its removal policy, generated from the module manifests.\n")
	b.WriteString("section: Modules\n")
	b.WriteString("weight: 36\n")
	b.WriteString("---\n\n")
	b.WriteString("<!-- Generated by ggg sync; DO NOT EDIT. Edit the declaring module's manifest. -->\n\n")
	b.WriteString("Generated from the manifests of every module in `gogogadget.lock.json`, which\n")
	b.WriteString("are the same records the planner resolves and the remover refuses on. A module\n")
	b.WriteString("absent from this page is not installed.\n\n")
	b.WriteString("`ggg info KIND/NAME` prints the same manifest in full, plus the files it owns,\n")
	b.WriteString("where to look at it, and the commands that verify it. See\n")
	b.WriteString("[Module anatomy and lifecycle](/docs/modules) for what each field means and\n")
	b.WriteString("[Module removal and data retention](/docs/module-removal) for the policies.\n\n")
	b.WriteString("**Requires** lists only direct dependencies; the installer expands the\n")
	b.WriteString("transitive closure itself.\n")

	for _, kind := range moduleKindOrder {
		modules := byKind[kind]
		if len(modules) == 0 {
			continue
		}
		fmt.Fprintf(&b, "\n## %s (%d)\n\n", kindHeading(kind), len(modules))
		b.WriteString("| Module | Title | Requires | Removal |\n")
		b.WriteString("|---|---|---|---|\n")
		for _, m := range modules {
			requires := "—"
			if len(m.Requires) > 0 {
				quoted := make([]string, 0, len(m.Requires))
				for _, id := range m.Requires {
					quoted = append(quoted, "`"+id+"`")
				}
				requires = strings.Join(quoted, " ")
			}
			fmt.Fprintf(&b, "| `%s` | %s | %s | `%s` |\n",
				m.ID, escapeTableCell(m.Title), requires, m.RemovalPolicy)
		}
	}

	_ = modulePath
	_ = ctx
	return &GeneratedFile{Path: "content/docs/module-reference.md", Content: b.String()}, nil
}

// kindHeading names one module kind for a reader rather than for a validator.
func kindHeading(kind ModuleKind) string {
	switch kind {
	case ModuleElement:
		return "Elements"
	case ModuleComponent:
		return "Components"
	case ModulePage:
		return "Pages"
	case ModuleWorkflow:
		return "Workflows"
	case ModuleSystem:
		return "Systems"
	}
	return string(kind)
}

// emitComponentReference renders the installed UI surface grouped by gallery
// family. The signature is the column that earns the page: it is the one fact a
// caller needs before writing the call, and it is declared in the manifest, so
// printing it here cannot disagree with what the gallery documents.
func emitComponentReference(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	type entry struct {
		contribution UIContribution
		module       string
	}
	byFamily := make(map[GalleryFamily][]entry, len(GalleryFamilies))
	total := 0
	for _, m := range orderedModules(lock, graph) {
		if m.TestOnly {
			continue
		}
		for _, c := range m.Runtime.UI {
			byFamily[c.Family] = append(byFamily[c.Family], entry{contribution: c, module: m.ID})
			total++
		}
	}
	for family := range byFamily {
		entries := byFamily[family]
		sort.Slice(entries, func(i, j int) bool {
			return entries[i].contribution.Name < entries[j].contribution.Name
		})
	}

	var b strings.Builder
	b.WriteString("---\n")
	b.WriteString("title: Component reference\n")
	b.WriteString("description: Every installed UI component with its exact signature and owning module, generated from the module manifests.\n")
	b.WriteString("section: Modules\n")
	b.WriteString("weight: 37\n")
	b.WriteString("---\n\n")
	b.WriteString("<!-- Generated by ggg sync; DO NOT EDIT. Edit the declaring module's manifest. -->\n\n")
	fmt.Fprintf(&b, "%d renderers, grouped by the gallery family each one appears under.\n", total)
	b.WriteString("Generated from the `runtime.ui` declarations of every installed module — the\n")
	b.WriteString("same records the gallery renders and the coverage test compares rendered\n")
	b.WriteString("`data-ui` markers against.\n\n")
	b.WriteString("Every renderer takes exactly one options struct and embeds `ui.Attrs` in it;\n")
	b.WriteString("see [UI foundations](/docs/ui-foundations) for the convention and\n")
	b.WriteString("[Component usage](/docs/components) for how to read an entry.\n\n")
	b.WriteString("**Engine** names the third-party runtime a component lazily loads, empty for\n")
	b.WriteString("the ones that need none. **Alpine** names the CSP-safe controller it\n")
	b.WriteString("registers. **Fallback** marks a component that declares what it does with no\n")
	b.WriteString("JavaScript at all; that declaration is a promise, and the a11y suite tests it.\n")

	for _, family := range GalleryFamilies {
		entries := byFamily[family]
		if len(entries) == 0 {
			continue
		}
		fmt.Fprintf(&b, "\n## %s (%d)\n\n", familyHeading(family), len(entries))
		b.WriteString("| Component | Signature | Module | Engine | Alpine | Fallback |\n")
		b.WriteString("|---|---|---|---|---|---|\n")
		for _, e := range entries {
			signature := "—"
			if e.contribution.Signature != "" {
				signature = "`" + escapeTableCell(e.contribution.Signature) + "`"
			}
			fallback := "—"
			if e.contribution.NativeFallback != "" {
				fallback = "yes"
			}
			fmt.Fprintf(&b, "| `%s` | %s | `%s` | %s | %s | %s |\n",
				e.contribution.Name, signature, e.module,
				codeOrDash(e.contribution.Engine), codeOrDash(e.contribution.Alpine), fallback)
		}
	}

	_ = modulePath
	_ = ctx
	return &GeneratedFile{Path: "content/docs/component-reference.md", Content: b.String()}, nil
}

// familyHeading titles one gallery family. The wire value is lower case because
// it is a URL segment; a heading is prose.
func familyHeading(family GalleryFamily) string {
	value := string(family)
	if value == "" {
		return value
	}
	return strings.ToUpper(value[:1]) + value[1:]
}

// codeOrDash renders an optional identifier as code, or an em dash when the
// module declared none. An empty cell reads as an omission; a dash is a stated
// absence.
func codeOrDash(value string) string {
	if value == "" {
		return "—"
	}
	return "`" + value + "`"
}

// envOwners maps each declared key to the module that declares it.
func envOwners(lock Lock, graph []Manifest) map[string]string {
	owner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, e := range m.Environment {
			owner[e.Key] = m.ID
		}
	}
	return owner
}

// boundsText states declared bounds in the reader's terms.
func boundsText(e EnvironmentVariable) string {
	if e.Type != EnvInt {
		return ""
	}
	switch {
	case e.Min != nil && e.Max != nil:
		return fmt.Sprintf("Integer between %d and %d", *e.Min, *e.Max)
	case e.Min != nil:
		return fmt.Sprintf("Integer >= %d", *e.Min)
	case e.Max != nil:
		return fmt.Sprintf("Integer <= %d", *e.Max)
	default:
		return "Integer"
	}
}

// escapeTableCell keeps a pipe in a description from splitting the column.
func escapeTableCell(s string) string {
	return strings.ReplaceAll(s, "|", "\\|")
}

func emitJobsRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	type job struct {
		moduleID string
		contrib  JobContribution
	}
	jobs := make([]job, 0)
	owner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, j := range m.Runtime.Jobs {
			// Two modules declaring one kind is a dispatch ambiguity: whichever
			// wins silently owns the other's queued rows.
			if previous, clash := owner[j.Kind]; clash {
				return nil, fmt.Errorf("job kind %q is declared by both %s and %s", j.Kind, previous, m.ID)
			}
			owner[j.Kind] = m.ID
			jobs = append(jobs, job{moduleID: m.ID, contrib: j})
		}
	}
	sort.Slice(jobs, func(i, j int) bool { return jobs[i].contrib.Kind < jobs[j].contrib.Kind })
	// The table must exist whenever the jobs package does: jobs.go references
	// these symbols, so emitting nothing would break a project that installs the
	// queue but has not yet declared a kind.
	installed := false
	for _, m := range graph {
		for _, f := range m.Files {
			if strings.HasPrefix(f.Target, "internal/jobs/") {
				installed = true
			}
		}
	}
	if len(jobs) == 0 && !installed && !hasJanitors(graph) {
		return nil, nil
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package jobs\n\n")

	b.WriteString("// workerDefinitions assembles every selected job declaration. The table names\n")
	b.WriteString("// declaration constructors and never knows a payload type, so a module's\n")
	b.WriteString("// handler stays typed while dispatch stays data.\n")
	b.WriteString("func workerDefinitions(w *Worker) []Definition {\n")
	b.WriteString("\treturn []Definition{\n")
	for _, j := range jobs {
		if !validIdentifier(j.contrib.Handler) {
			return nil, fmt.Errorf("job %s: handler %q is not a Go identifier", j.contrib.Kind, j.contrib.Handler)
		}
		fmt.Fprintf(&b, "\t\tw.%s(),\n", j.contrib.Handler)
	}
	b.WriteString("\t}\n}\n\n")

	b.WriteString("// SchedulableKinds are the kinds a schedule row may reference. Derived from\n")
	b.WriteString("// the declarations, so a kind cannot be scheduled unless its module said it\n")
	b.WriteString("// may be — a schedule pointing at a one-shot handler would fire it forever.\n")
	b.WriteString("var SchedulableKinds = []string{\n")
	for _, j := range jobs {
		if j.contrib.Schedulable {
			fmt.Fprintf(&b, "\t%s,\n", goString(j.contrib.Kind))
		}
	}
	b.WriteString("}\n\n")

	// Janitor sweeps, same discipline: declared by the module that owns the table
	// each one deletes from.
	type janitor struct {
		moduleID string
		contrib  JanitorContribution
	}
	janitors := make([]janitor, 0)
	sweepOwner := make(map[string]string)
	for _, m := range orderedModules(lock, graph) {
		for _, jn := range m.Runtime.Janitors {
			if previous, clash := sweepOwner[jn.Name]; clash {
				return nil, fmt.Errorf("janitor %q is declared by both %s and %s", jn.Name, previous, m.ID)
			}
			sweepOwner[jn.Name] = m.ID
			janitors = append(janitors, janitor{moduleID: m.ID, contrib: jn})
		}
	}
	sort.Slice(janitors, func(i, j int) bool { return janitors[i].contrib.Name < janitors[j].contrib.Name })

	b.WriteString("// workerJanitors is every declared cleanup sweep. The pass runs all of them\n")
	b.WriteString("// and logs per sweep, so one failing sweep cannot strand the rest.\n")
	b.WriteString("func workerJanitors(w *Worker) []Janitor {\n")
	b.WriteString("\treturn []Janitor{\n")
	for _, jn := range janitors {
		if !validIdentifier(jn.contrib.Handler) {
			return nil, fmt.Errorf("janitor %s: handler %q is not a Go identifier", jn.contrib.Name, jn.contrib.Handler)
		}
		fmt.Fprintf(&b, "\t\t{Name: %s, Sweep: w.%s},\n", goString(jn.contrib.Name), jn.contrib.Handler)
	}
	b.WriteString("\t}\n}\n\n")

	b.WriteString("// declaredAttempts is the budget each kind declares. Enqueue helpers write it\n")
	b.WriteString("// onto the row, and the row is dispatch truth from then on.\n")
	b.WriteString("var declaredAttempts = map[string]int{\n")
	for _, j := range jobs {
		attempts := j.contrib.MaxAttempts
		if attempts == 0 {
			attempts = DefaultJobAttempts
		}
		fmt.Fprintf(&b, "\t%s: %d,\n", goString(j.contrib.Kind), attempts)
	}
	b.WriteString("}\n")

	_ = ctx
	return &GeneratedFile{Path: "internal/jobs/jobs_registry_gen.go", Content: b.String()}, nil
}

func validateRoutePatterns(patterns []routePattern) (err error) {
	mux := http.NewServeMux()
	for _, p := range patterns {
		if err := registerRoutePattern(mux, p); err != nil {
			return err
		}
	}
	return nil
}

// registerRoutePattern isolates one registration so a panic names the route that
// caused it rather than aborting generation with a bare runtime message.
func registerRoutePattern(mux *http.ServeMux, p routePattern) (err error) {
	defer func() {
		if recovered := recover(); recovered != nil {
			err = fmt.Errorf("route %s (%s): pattern %q %q is invalid or conflicts: %v",
				p.id, p.module, p.method, p.pattern, recovered)
		}
	}()
	mux.Handle(p.method+" "+p.pattern, http.NotFoundHandler())
	return nil
}
